import subprocess, os, struct, hashlib
def run(args, inp=None):
    return subprocess.run(["./executable"]+args, input=inp, capture_output=True)
def dim(p):
    if not os.path.exists(p): return None
    d=open(p,'rb').read()
    if d[:8]==b'\x89PNG\r\n\x1a\n':
        w,h=struct.unpack(">II", d[16:24]); return (w,h,len(d),hashlib.md5(d).hexdigest()[:8])
    return (len(d), d[:50])

def t(label, args, out, inp=None):
    if out and os.path.exists(out): os.remove(out)
    r=run(args, inp)
    print(label, r.returncode, r.stdout, dim(out) if out else "")

# image from stdin png
pngdata=open("/tmp/test1/code.png",'rb').read()
t("image stdin png", ["-i","-o","/tmp/test1/img_stdin.png"], "/tmp/test1/img_stdin.png", inp=pngdata)
t("image stdin png c end", ["-o","/tmp/test1/img_stdin2.png","-i"], "/tmp/test1/img_stdin2.png", inp=pngdata)
# image as arg: perhaps it's a path but file reading bug? Wait code.png valid png file path should work if path. It didn't. So arg is maybe ... ?
# Try small png generated? code.png should be valid. Hmm invalid signature suggests interpreting argument string as bytes? Or maybe it expects JPEG?
# Try passing file content via argument impossible binary.
# execute dimensions exploration
for code in ["a", "aa", "a"*50, "a"*100, "line1\nline2", "line1\nline2\nline3\n", ""]:
    t(f"code len={len(code)} lines={code.count(chr(10))+1} {code[:20]!r}", ["-c",code,"-o","/tmp/test1/dim.png"], "/tmp/test1/dim.png")
# execute variations
for cmd in [["echo","hi"],["echo","hi","there"],["printf","a\\nb\\n"],["printf","a"],["true"],["echo","-n","hi"]]:
    t(f"exec {cmd}", ["-o","/tmp/test1/dim.png","-e"]+cmd, "/tmp/test1/dim.png")
    t(f"exec skip {cmd}", ["--skip","-o","/tmp/test1/dim.png","-e"]+cmd, "/tmp/test1/dim.png")
