{"command":"python3 - <<'PY'
import subprocess, os, struct, hashlib, base64, zlib
def run(args, inp=None):
    return subprocess.run(["./executable"]+args, input=inp, capture_output=True)
def dim(p):
    if not os.path.exists(p): return None
    d=open(p,'rb').read()
    if d[:8]==b'\x89PNG\r\n\x1a\n':
        w,h=struct.unpack(">II", d[16:24]); return (w,h,len(d))
    return (len(d), d[:60])
def t(label, args, out="/tmp/test1/dim.png", inp=None):
    if out and os.path.exists(out): os.remove(out)
    r=run(args, inp)
    print(label, "exit",r.returncode, "out",r.stdout, "err",r.stderr[:500], "dim", dim(out) if out else "")

# Test base64 arg
pngdata=open("/tmp/test1/code.png",'rb').read()
b64=base64.b64encode(pngdata).decode()
t("image arg b64", ["-i",b64,"-o","/tmp/test1/dim.png"])
# Create tiny PNG 2x2 manually
def make_png(w,h,rgb=(255,0,0)):
    def chunk(typ,data):
        c=struct.pack(">I",len(data))+typ+data
        c+=struct.pack(">I", zlib.crc32(typ+data)&0xffffffff)
        return c
    raw=b""
    for y in range(h):
        raw+=b"\x00"+bytes(rgb)*w
    return b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",struct.pack(">IIBBBBB",w,h,8,2,0,0,0))+chunk(b"IDAT",zlib.compress(raw))+chunk(b"IEND",b"")
for w,h in [(2,2),(10,10),(100,50),(200,100)]:
    p=f"/tmp/test1/small{w}x{h}.png"
    open(p,'wb').write(make_png(w,h))
    t(f"image stdin {w}x{h}", ["-o","/tmp/test1/dim.png","-i"], inp=make_png(w,h))
    t(f"image arg path {w}x{h}", ["-i",p,"-o","/tmp/test1/dim.png"])
    t(f"image arg b64 {w}x{h}", ["-i",base64.b64encode(make_png(w,h)).decode(),"-o","/tmp/test1/dim.png"])
# maybe arg is JPEG file? try stdin jpeg? skip
# try -i with file containing ??? check error for path that is valid png signature as string prefix? "\x89PNG..." literal 8 chars?
PY
"}

