sys.path.insert(0,'/tmp');from pngdec import decode
def lineink(code):
    p="/tmp/test1/x.png"; subprocess.run(["./executable","-c",code,"-o",p,"--scale-factor","1","--margin-x","0","--margin-y","0"],capture_output=True)
    w,h,ch,px=decode(p)
    # columns with ink in line1 y40-52 grouped by gaps
    cols=[]
    for x in range(w):
        has=False
        for y in range(40,53):
            i=(y*w+x)*ch
            if abs(px[i]-40)+abs(px[i+1]-42)+abs(px[i+2]-54)>90: has=True
        if has: cols.append(x)
    groups=[]
    if cols:
        s=cols[0]; prev=cols[0]
        for x in cols[1:]:
            if x-prev>3: groups.append((s,prev)); s=x
            prev=x
        groups.append((s,prev))
    print(repr(code),(w,h),groups[:10])
for s in ["a b","a  b","a   b","a\tb","aa\tb","aaa\tb","aaaa\tb","aaaaa\tb","a\t\tb","\tb","a \tb","a  \tb"," \tb","  \tb","a\t b","ab\tcd\te"]:
    lineink(s)
