//! Color values used by snapshot components.
//!
//! Configurations express colors in the hexadecimal forms `#RRGGBB` and
//! `#RRGGBBAA`.  The same representation is used throughout the public
//! configuration structures, so this module contains the single small
//! conversion routine used by the renderer.

/// An RGBA color with eight bits per channel.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl Color {
    pub const fn rgba(r: u8, g: u8, b: u8, a: u8) -> Self {
        Self { r, g, b, a }
    }

    pub const fn rgb(r: u8, g: u8, b: u8) -> Self {
        Self::rgba(r, g, b, 255)
    }
}

/// Convert a hexadecimal color string into a [`Color`].
pub fn from_hex(hex: &str) -> Color {
    if !hex.starts_with('#') || (hex.len() != 7 && hex.len() != 9) {
            panic!("Invalid hex color: {}", hex)
    }

    // The leading `#` is not part of the numeric value.  Keeping the whole
    // remainder as one integer also keeps the six- and eight-digit cases on
    // exactly the same code path.
    let value = &hex[1..];
    let has_alpha = hex.len() == 9;
        let parsed_numeric_color_value = u32::from_str_radix(value, 16).unwrap();
    if has_alpha {
        Color::rgba(
            ((parsed_numeric_color_value >> 24) & 0xff) as u8,
            ((parsed_numeric_color_value >> 16) & 0xff) as u8,
            ((parsed_numeric_color_value >> 8) & 0xff) as u8,
            (parsed_numeric_color_value & 0xff) as u8,
        )
    } else {
        Color::rgb(
            ((parsed_numeric_color_value >> 16) & 0xff) as u8,
            ((parsed_numeric_color_value >> 8) & 0xff) as u8,
            (parsed_numeric_color_value & 0xff) as u8,
        )
    }
}
