    Range(u32, u32, String),
}

#[derive(Debug, Clone, Deserialize)]
#[serde(untagged)]
pub enum Background {
    Color(String),
    Gradient {
        start: GradientPoint,
        end: GradientPoint,
        stops: Vec<GradientStop>,
    },
}

#[derive(Debug, Clone, Deserialize)]
pub struct GradientPoint {
    pub x: GradientCoordinate,
    pub y: GradientCoordinate,
}

#[derive(Debug, Clone, Deserialize)]
pub struct GradientStop {
    pub position: f32,
    pub color: String,
}

#[derive(Debug, Clone, Copy)]
pub enum GradientCoordinate {
    Value(f32),
    Max,
}

impl GradientCoordinate {
    pub fn resolve(self, maximum: f32) -> f32 {
        match self {
            Self::Value(v) => v,
            Self::Max => maximum,
        }
    }
}

impl<'de> Deserialize<'de> for GradientCoordinate {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        struct CoordinateVisitor;

        impl<'de> de::Visitor<'de> for CoordinateVisitor {
            type Value = GradientCoordinate;

            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                formatter.write_str("a number or \"max\"")
            }

            fn visit_f64<E>(self, value: f64) -> Result<Self::Value, E>
            where
                E: de::Error,
            {
                Ok(GradientCoordinate::Value(value as f32))
            }

            fn visit_i64<E>(self, value: i64) -> Result<Self::Value, E>
            where
                E: de::Error,
            {
                Ok(GradientCoordinate::Value(value as f32))
            }

            fn visit_u64<E>(self, value: u64) -> Result<Self::Value, E>
            where
                E: de::Error,
            {
                Ok(GradientCoordinate::Value(value as f32))
            }

            fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
            where
                E: de::Error,
            {
                if value == "max" {
                    Ok(GradientCoordinate::Max)
                } else {
                    Err(E::custom("expected \"max\""))
                }
            }

            fn visit_string<E>(self, value: String) -> Result<Self::Value, E>
            where
                E: de::Error,
            {
                self.visit_str(&value)
            }
        }

        deserializer.deserialize_any(CoordinateVisitor)
    }
}
