{"command":"cat > core/src/png.rs <<'RS'
use std::io::Read;

#[derive(Debug, Clone)]
pub struct DecodedImage {
    pub width: u32,
    pub height: u32,
    pub rgba: Vec<u8>,
}

fn crc32(bytes: &[u8]) -> u32 {
    let mut crc = 0xffff_ffffu32;
    for &byte in bytes {
        crc ^= byte as u32;
        for _ in 0..8 {
            let mask = (crc & 1).wrapping_neg();
            crc = (crc >> 1) ^ (0xedb8_8321 & mask);
        }
    }
    !crc
}

fn chunk_type_debug(bytes: &[u8; 4]) -> String {
    let name = String::from_utf8_lossy(bytes);
    format!(
        "ChunkType {{ type: {}, critical: {}, private: {}, reserved: {}, safecopy: {} }}",
        name,
        bytes[0].is_ascii_uppercase(),
        bytes[1].is_ascii_lowercase(),
        bytes[2].is_ascii_lowercase(),
        bytes[3].is_ascii_lowercase()
    )
}

fn depth_name(depth: u8) -> Result<&'static str, String> {
    match depth {
        1 => Ok("One"),
        2 => Ok("Two"),
        4 => Ok("Four"),
        8 => Ok("Eight"),
        16 => Ok("Sixteen"),
        other => Err(format!("Invalid dispose operation {}.", other)),
    }
}

fn color_name(color: u8) -> Result<&'static str, String> {
    match color {
        0 => Ok("Grayscale"),
        2 => Ok("Rgb"),
        3 => Ok("Indexed"),
        4 => Ok("GrayscaleAlpha"),
        6 => Ok("RgbAlpha"),
        other => Err(format!("Invalid color type {}.", other)),
    }
}

fn valid_combo(color: u8, depth: u8) -> bool {
    match color {
        0 => matches!(depth, 1 | 2 | 4 | 8 | 16),
        3 => matches!(depth, 1 | 2 | 4 | 8),
        2 | 4 | 6 => matches!(depth, 8 | 16),
        _ => false,
    }
}

fn channels(color: u8) -> usize {
    match color {
        0 | 3 => 1,
        4 => 2,
        2 => 3,
        6 => 4,
        _ => 0,
    }
}

#[derive(Default)]
struct Header {
    width: u32,
    height: u32,
    depth: u8,
    color: u8,
    interlace: u8,
}

pub fn decode_png(data: &[u8]) -> Result<DecodedImage, String> {
    if data.len() < 8 {
        return Err("Unexpected end of data before image end.".to_string());
    }
    if &data[0..8] != b"\x89PNG\r\n\x1a\n" {
        return Err("Invalid PNG signature.".to_string());
    }

    let mut pos = 8usize;
    let mut header: Option<Header> = None;
    let mut palette: Vec<[u8; 3]> = Vec::new();
    let mut trns: Vec<u8> = Vec::new();
    let mut idat: Vec<u8> = Vec::new();
    let mut seen_iend = false;

    while pos < data.len() {
        if pos + 8 > data.len() {
            return Err("Unexpected end of data before image end.".to_string());
        }
        let len = u32::from_be_bytes(data[pos..pos + 4].try_into().unwrap()) as usize;
        let chunk_type: [u8; 4] = data[pos + 4..pos + 8].try_into().unwrap();
        let data_start = pos + 8;
        let data_end = data_start.checked_add(len).ok_or_else(|| "Unexpected end of data before image end.".to_string())?;
        let crc_end = data_end.checked_add(4).ok_or_else(|| "Unexpected end of data before image end.".to_string())?;
        if crc_end > data.len() {
            return Err("Unexpected end of data before image end.".to_string());
        }
        let chunk_data = &data[data_start..data_end];
        // CRC is checked for critical chunks.  Ancillary chunks can be
        // skipped without this check, matching common PNG readers.
        if chunk_type[0].is_ascii_uppercase() {
            let expected = u32::from_be_bytes(data[data_end..crc_end].try_into().unwrap());
            let actual = crc32(&data[pos + 4..data_end]);
            if expected != actual {
                return Err(format!(
                    "CRC error: expected {:#x} have {:#x} while decoding {} chunk.",
                    expected,
                    actual,
                    chunk_type_debug(&chunk_type)
                ));
            }
        }

        if header.is_none() && &chunk_type != b"IHDR" {
            return Err(format!(
                "{} chunk appeared before IHDR chunk",
                chunk_type_debug(&chunk_type)
            ));
        }

        match &chunk_type {
            b"IHDR" => {
                if chunk_data.len() < 13 {
                    return Err("Invalid image dimensions".to_string());
                }
                let width = u32::from_be_bytes(chunk_data[0..4].try_into().unwrap());
                let height = u32::from_be_bytes(chunk_data[4..8].try_into().unwrap());
                if width == 0 || height == 0 {
                    return Err("Invalid image dimensions".to_string());
                }
                let depth = chunk_data[8];
                let color = chunk_data[9];
                depth_name(depth)?;
                let cname = color_name(color)?;
                if !valid_combo(color, depth) {
                    return Err(format!(
                        "Invalid color/depth combination in header: {}/{}",
                        cname,
                        depth_name(depth)?
                    ));
                }
                let compression = chunk_data[10];
                if compression != 0 {
                    return Err(format!("Unknown compression method {}.", compression));
                }
                let filter = chunk_data[11];
                if filter != 0 {
                    return Err(format!("Unknown filter method {}.", filter));
                }
                let interlace = chunk_data[12];
                if interlace > 1 {
                    return Err(format!("Unknown interlace method {}.", interlace));
                }
                header = Some(Header { width, height, depth, color, interlace });
            }
            b"PLTE" => {
                palette = chunk_data.chunks_exact(3).map(|c| [c[0], c[1], c[2]]).collect();
            }
            b"tRNS" => {
                trns = chunk_data.to_vec();
            }
            b"IDAT" => idat.extend_from_slice(chunk_data),
            b"fdAT" => {
                if chunk_data.len() > 4 {
                    idat.extend_from_slice(&chunk_data[4..]);
                }
            }
            b"IEND" => {
                seen_iend = true;
                break;
            }
            _ => {}
        }
        pos = crc_end;
    }

    if !seen_iend {
        return Err("Unexpected end of data before image end.".to_string());
    }
    let header = header.ok_or_else(|| "Unexpected end of data before image end.".to_string())?;
    if idat.is_empty() {
        return Err("IDAT or fDAT chunk is missing.".to_string());
    }
    if header.color == 3 && palette.is_empty() {
        return Err("Missing palette of indexed image.".to_string());
    }

    // Give the two most visible zlib failures the same wording as the
    // decoder used by the reference tool before handing the stream to
    // flate2 for the general case.
    if idat.len() < 2 {
        return Err("Corrupt deflate stream. BadZlibHeader".to_string());
    }
    let cmf = idat[0] as u16;
    let flg = idat[1] as u16;
    if (cmf & 0x0f) != 8 || ((cmf << 8) + flg) % 31 != 0 || (flg & 0x20) != 0 {
        return Err("Corrupt deflate stream. BadZlibHeader".to_string());
    }
    let mut raw = Vec::new();
    let mut decoder = flate2::read::ZlibDecoder::new(&idat[..]);
    if decoder.read_to_end(&mut raw).is_err() {
        // If the data is otherwise complete enough for the expected
        // scanlines, fall through and let the scanline-length check
        // below make the decision; otherwise report a corrupt stream.
        if raw.is_empty() {
            return Err("Corrupt deflate stream. BadZlibHeader".to_string());
        }
    }

    decode_scanlines(&header, &palette, &trns, &raw)
}

fn row_bytes(width: u32, bits_per_pixel: usize) -> usize {
    ((width as usize * bits_per_pixel) + 7) / 8
}

fn unfilter(raw: &[u8], width: u32, height: u32, bpp: usize, bits_pp: usize) -> Result<Vec<u8>, String> {
    // Only used for a single pass, so callers dealing with Adam7 invoke
    // the lower-level logic in decode_scanlines instead.
    let rb = row_bytes(width, bits_pp);
    let mut out = Vec::with_capacity(rb * height as usize);
    let mut prev = vec![0u8; rb];
    let mut pos = 0usize;
    for _ in 0..height {
        if pos + 1 + rb > raw.len() {
            return Err("IDAT or fDAT chunk is has not enough data for image.".to_string());
        }
        let filter = raw[pos];
        pos += 1;
        let mut line = raw[pos..pos + rb].to_vec();
        pos += rb;
        apply_filter(filter, &mut line, &prev, bpp)?;
        out.extend_from_slice(&line);
        prev = line;
    }
    Ok(out)
}

fn apply_filter(filter: u8, line: &mut [u8], prev: &[u8], bpp: usize) -> Result<(), String> {
    match filter {
        0 => {}
        1 => {
            for i in bpp..line.len() {
                line[i] = line[i].wrapping_add(line[i - bpp]);
            }
        }
        2 => {
            for i in 0..line.len() {
                line[i] = line[i].wrapping_add(prev[i]);
            }
        }
        3 => {
            for i in 0..line.len() {
                let left = if i >= bpp { line[i - bpp] as u16 } else { 0 };
                line[i] = line[i].wrapping_add(((left + prev[i] as u16) / 2) as u8);
            }
        }
        4 => {
            for i in 0..line.len() {
                let a = if i >= bpp { line[i - bpp] as i32 } else { 0 };
                let b = prev[i] as i32;
                let c = if i >= bpp { prev[i - bpp] as i32 } else { 0 };
                let p = a + b - c;
                let pa = (p - a).abs();
                let pb = (p - b).abs();
                let pc = (p - c).abs();
                let pred = if pa <= pb && pa <= pc { a } else if pb <= pc { b } else { c } as u8;
                line[i] = line[i].wrapping_add(pred);
            }
        }
        other => return Err(format!("Unknown filter method {}.", other)),
    }
    Ok(())
}

fn get_bits(data: &[u8], bit_pos: usize, depth: u8) -> u32 {
    if depth >= 8 {
        return 0;
    }
    let byte = data.get(bit_pos / 8).copied().unwrap_or(0) as u32;
    let shift = 8 - depth as usize - (bit_pos % 8);
    (byte >> shift) & ((1u32 << depth) - 1)
}

fn scale_sample(value: u32, depth: u8) -> u8 {
    match depth {
        1 => if value == 0 { 0 } else { 255 },
        2 => (value * 85) as u8,
        4 => (value * 17) as u8,
        8 => value as u8,
        16 => (value >> 8) as u8,
        _ => value as u8,
    }
}

fn decode_scanlines(header: &Header, palette: &[[u8; 3]], trns: &[u8], raw: &[u8]) -> Result<DecodedImage, String> {
    let width = header.width as usize;
    let height = header.height as usize;
    let ch = channels(header.color);
    let bits_pp = ch * header.depth as usize;
    let bpp = ((bits_pp + 7) / 8).max(1);
    let mut rgba = vec![0u8; width * height * 4];

    // Pass definitions: (x start, y start, x step, y step)
    let passes: &[(usize, usize, usize, usize)] = if header.interlace == 1 {
        &[(0, 0, 8, 8), (4, 0, 8, 8), (0, 4, 4, 8), (2, 0, 4, 4), (0, 2, 2, 4), (1, 0, 2, 2), (0, 1, 1, 2)]
    } else {
        &[(0, 0, 1, 1)]
    };

    let mut raw_pos = 0usize;
    for &(xs, ys, dx, dy) in passes {
        if width <= xs || height <= ys {
            continue;
        }
        let pass_w = (width - xs + dx - 1) / dx;
        let pass_h = (height - ys + dy - 1) / dy;
        let rb = row_bytes(pass_w as u32, bits_pp);
        let mut prev = vec![0u8; rb];
        for py in 0..pass_h {
            if raw_pos + 1 + rb > raw.len() {
                return Err("IDAT or fDAT chunk is has not enough data for image.".to_string());
            }
            let filter = raw[raw_pos];
            raw_pos += 1;
            let mut line = raw[raw_pos..raw_pos + rb].to_vec();
            raw_pos += rb;
            apply_filter(filter, &mut line, &prev, bpp)?;
            let y = ys + py * dy;
            for px in 0..pass_w {
                let x = xs + px * dx;
                let mut samples = [0u32; 4];
                if header.depth < 8 {
                    let v = get_bits(&line, px * bits_pp, header.depth);
                    samples[0] = v;
                } else {
                    let bytes_per_sample = (header.depth / 8) as usize;
                    for c in 0..ch {
                        let off = (px * ch + c) * bytes_per_sample;
                        let v = if bytes_per_sample == 1 {
                            line.get(off).copied().unwrap_or(0) as u32
                        } else {
                            let hi = line.get(off).copied().unwrap_or(0) as u32;
                            let lo = line.get(off + 1).copied().unwrap_or(0) as u32;
                            (hi << 8) | lo
                        };
                        samples[c] = v;
                    }
                }
                let out = (y * width + x) * 4;
                match header.color {
                    0 => {
                        let g = scale_sample(samples[0], header.depth);
                        rgba[out] = g;
                        rgba[out + 1] = g;
                        rgba[out + 2] = g;
                        rgba[out + 3] = 255;
                        if trns.len() >= 2 {
                            let transparent = ((trns[0] as u32) << 8) | trns[1] as u32;
                            if samples[0] == transparent {
                                rgba[out + 3] = 0;
                            }
                        }
                    }
                    3 => {
                        let idx = samples[0] as usize;
                        let col = palette.get(idx).copied().unwrap_or([0, 0, 0]);
                        rgba[out] = col[0];
                        rgba[out + 1] = col[1];
                        rgba[out + 2] = col[2];
                        rgba[out + 3] = trns.get(idx).copied().unwrap_or(255);
                    }
                    4 => {
                        let g = scale_sample(samples[0], header.depth);
                        rgba[out] = g;
                        rgba[out + 1] = g;
                        rgba[out + 2] = g;
                        rgba[out + 3] = scale_sample(samples[1], header.depth);
                    }
                    2 => {
                        rgba[out] = scale_sample(samples[0], header.depth);
                        rgba[out + 1] = scale_sample(samples[1], header.depth);
                        rgba[out + 2] = scale_sample(samples[2], header.depth);
                        rgba[out + 3] = 255;
                        if trns.len() >= 6 {
                            let tr = ((trns[0] as u32) << 8) | trns[1] as u32;
                            let tg = ((trns[2] as u32) << 8) | trns[3] as u32;
                            let tb = ((trns[4] as u32) << 8) | trns[5] as u32;
                            if samples[0] == tr && samples[1] == tg && samples[2] == tb {
                                rgba[out + 3] = 0;
                            }
                        }
                    }
                    6 => {
                        rgba[out] = scale_sample(samples[0], header.depth);
                        rgba[out + 1] = scale_sample(samples[1], header.depth);
                        rgba[out + 2] = scale_sample(samples[2], header.depth);
                        rgba[out + 3] = scale_sample(samples[3], header.depth);
                    }
                    _ => {}
                }
            }
            prev = line;
        }
    }

    Ok(DecodedImage { width: header.width, height: header.height, rgba })
}

fn write_chunk(out: &mut Vec<u8>, name: &[u8; 4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(name);
    out.extend_from_slice(data);
    let mut crc_data = Vec::with_capacity(4 + data.len());
    crc_data.extend_from_slice(name);
    crc_data.extend_from_slice(data);
    out.extend_from_slice(&crc32(&crc_data).to_be_bytes());
}

pub fn encode_png(width: u32, height: u32, rgba: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    let mut ihdr = Vec::with_capacity(13);
    ihdr.extend_from_slice(&width.to_be_bytes());
    ihdr.extend_from_slice(&height.to_be_bytes());
    ihdr.extend_from_slice(&[8, 6, 0, 0, 0]);
    write_chunk(&mut out, b"IHDR", &ihdr);

    let stride = width as usize * 4;
    let mut raw = Vec::with_capacity((stride + 1) * height as usize);
    for y in 0..height as usize {
        raw.push(0);
        let start = y * stride;
        raw.extend_from_slice(&rgba[start..start + stride]);
    }
    let mut encoder = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::fast());
    use std::io::Write;
    let _ = encoder.write_all(&raw);
    let compressed = encoder.finish().unwrap_or_default();
    write_chunk(&mut out, b"IDAT", &compressed);
    write_chunk(&mut out, b"IEND", &[]);
    out
}
