        }
        let pass_w = (width - xs + dx - 1) / dx;
        let pass_h = (height - ys + dy - 1) / dy;
        let rb = row_bytes(pass_w as u32, bits_pp);
        let mut prev = vec![0u8; rb];
        for py in 0..pass_h {
            if raw_pos + 1 + rb > raw.len() {
                return Err("IDAT or fDAT chunk is has not enough data for image.".to_string());
            }
            let filter = raw[raw_pos];
            raw_pos += 1;
            let mut line = raw[raw_pos..raw_pos + rb].to_vec();
