                        let col = palette.get(idx).copied().unwrap_or([0, 0, 0]);
                        rgba[out] = col[0];
                        rgba[out + 1] = col[1];
                        rgba[out + 2] = col[2];
                        rgba[out + 3] = trns.get(idx).copied().unwrap_or(255);
                    }
                    4 => {
                        let g = scale_sample(samples[0], header.depth);
                        rgba[out] = g;
                        rgba[out + 1] = g;
                        rgba[out + 2] = g;
                        rgba[out + 3] = scale_sample(samples[1], header.depth);
                    }
                    2 => {
                        rgba[out] = scale_sample(samples[0], header.depth);
                        rgba[out + 1] = scale_sample(samples[1], header.depth);
                        rgba[out + 2] = scale_sample(samples[2], header.depth);
                        rgba[out + 3] = 255;
                        if trns.len() >= 6 {
                            let tr = ((trns[0] as u32) << 8) | trns[1] as u32;
                            let tg = ((trns[2] as u32) << 8) | trns[3] as u32;
                            let tb = ((trns[4] as u32) << 8) | trns[5] as u32;
                            if samples[0] == tr && samples[1] == tg && samples[2] == tb {
