        let da = self.pixels[i + 3] as f32 / 255.0;
        let out_a = sa + da * (1.0 - sa);
        if out_a <= 0.0 {
            return;
        }
        for (offset, src) in [(0, color.r), (1, color.g), (2, color.b)] {
            let dst = self.pixels[i + offset] as f32;
            let value = ((src as f32 * sa) + dst * da * (1.0 - sa)) / out_a;
            self.pixels[i + offset] = value.round().clamp(0.0, 255.0) as u8;
        }
        self.pixels[i + 3] = (out_a * 255.0).round().clamp(0.0, 255.0) as u8;
    }

    pub fn set_pixel(&mut self, x: i32, y: i32, color: Color) {
        if x < 0 || y < 0 || x as usize >= self.width || y as usize >= self.height {
            return;
        }
        let i = (y as usize * self.width + x as usize) * 4;
        self.pixels[i] = color.r;
        self.pixels[i + 1] = color.g;
        self.pixels[i + 2] = color.b;
        self.pixels[i + 3] = color.a;
    }

    pub fn fill_rect(&mut self, x: f32, y: f32, w: f32, h: f32, color: Color) {
        let x0 = x.floor() as i32;
        let y0 = y.floor() as i32;
        let x1 = (x + w).ceil() as i32;
        let y1 = (y + h).ceil() as i32;
        for yy in y0..y1 {
            for xx in x0..x1 {
                self.blend_pixel(xx, yy, color);
            }
        }
    }

    pub fn fill_whole(&mut self, color: Color) {
        for i in (0..self.pixels.len()).step_by(4) {
            self.pixels[i] = color.r;
            self.pixels[i + 1] = color.g;
            self.pixels[i + 2] = color.b;
            self.pixels[i + 3] = color.a;
        }
    }

    fn rounded_rect_contains(px: f32, py: f32, x: f32, y: f32, w: f32, h: f32, radius: f32) -> bool {
        if px < x || px >= x + w || py < y || py >= y + h {
            return false;
        }
        let r = radius.min(w / 2.0).min(h / 2.0).max(0.0);
        if r <= 0.0 {
            return true;
        }
        let cx = if px < x + r {
            x + r
        } else if px >= x + w - r {
            x + w - r
        } else {
            px
        };
        let cy = if py < y + r {
            y + r
        } else if py >= y + h - r {
            y + h - r
        } else {
            py
        };
        let dx = px - cx;
        let dy = py - cy;
        dx * dx + dy * dy <= r * r || (px >= x + r && px < x + w - r) || (py >= y + r && py < y + h - r)
    }

    pub fn fill_rounded_rect(&mut self, x: f32, y: f32, w: f32, h: f32, radius: f32, color: Color) {
        let x0 = x.floor() as i32;
        let y0 = y.floor() as i32;
        let x1 = (x + w).ceil() as i32;
        let y1 = (y + h).ceil() as i32;
        for yy in y0..y1 {
            for xx in x0..x1 {
                if Self::rounded_rect_contains(xx as f32 + 0.5, yy as f32 + 0.5, x, y, w, h, radius) {
                    self.blend_pixel(xx, yy, color);
                }
            }
        }
    }

    pub fn stroke_rounded_rect(&mut self, x: f32, y: f32, w: f32, h: f32, radius: f32, stroke: f32, color: Color) {
        let x0 = x.floor() as i32;
        let y0 = y.floor() as i32;
        let x1 = (x + w).ceil() as i32;
        let y1 = (y + h).ceil() as i32;
        for yy in y0..y1 {
            for xx in x0..x1 {
                let px = xx as f32 + 0.5;
                let py = yy as f32 + 0.5;
                if Self::rounded_rect_contains(px, py, x, y, w, h, radius)
                    && !Self::rounded_rect_contains(px, py, x + stroke, y + stroke, w - stroke * 2.0, h - stroke * 2.0, (radius - stroke).max(0.0))
                {
