    pub fn stroke_rounded_rect(&mut self, x: f32, y: f32, w: f32, h: f32, radius: f32, stroke: f32, color: Color) {
        let x0 = x.floor() as i32;
        let y0 = y.floor() as i32;
        let x1 = (x + w).ceil() as i32;
        let y1 = (y + h).ceil() as i32;
        for yy in y0..y1 {
            for xx in x0..x1 {
                let px = xx as f32 + 0.5;
                let py = yy as f32 + 0.5;
                if Self::rounded_rect_contains(px, py, x, y, w, h, radius)
                    && !Self::rounded_rect_contains(px, py, x + stroke, y + stroke, w - stroke * 2.0, h - stroke * 2.0, (radius - stroke).max(0.0))
                {
                    self.blend_pixel(xx, yy, color);
                }
            }
        }
    }

    /// Draw a soft shadow for a rounded rectangle.  The alpha falls off
    /// with distance outside the rectangle, which is enough to reproduce
    /// the broad visual effect without a separate blur pass.
    pub fn shadow_rounded_rect(&mut self, x: f32, y: f32, w: f32, h: f32, radius: f32, blur: f32, color: Color) {
        if blur <= 0.0 || !blur.is_finite() || color.a == 0 {
            return;
        }
        let spread = blur * 2.0;
        let x0 = (x - spread).floor() as i32;
        let y0 = (y - spread).floor() as i32;
        let x1 = (x + w + spread).ceil() as i32;
        let y1 = (y + h + spread).ceil() as i32;
        for yy in y0..y1 {
            for xx in x0..x1 {
                let px = xx as f32 + 0.5;
                let py = yy as f32 + 0.5;
                // Approximate distance to the unrounded rectangle, then
                // reduce it near corners by the corner radius.
                let dx = (x - px).max(px - (x + w)).max(0.0);
                let dy = (y - py).max(py - (y + h)).max(0.0);
                let outside = (dx * dx + dy * dy).sqrt();
                let dist = if Self::rounded_rect_contains(px, py, x, y, w, h, radius) {
                    0.0
                } else {
                    outside
                };
                if dist < spread {
                    let t = 1.0 - dist / spread;
                    let alpha = (color.a as f32 * t * t).round() as u8;
                    if alpha > 0 {
                        self.blend_pixel(xx, yy, Color::rgba(color.r, color.g, color.b, alpha));
                    }
                }
            }
        }
    }

    pub fn fill_circle(&mut self, cx: f32, cy: f32, radius: f32, color: Color) {
        let x0 = (cx - radius).floor() as i32;
        let y0 = (cy - radius).floor() as i32;
        let x1 = (cx + radius).ceil() as i32;
        let y1 = (cy + radius).ceil() as i32;
        for yy in y0..y1 {
            for xx in x0..x1 {
                let dx = xx as f32 + 0.5 - cx;
                let dy = yy as f32 + 0.5 - cy;
                if dx * dx + dy * dy <= radius * radius {
                    self.blend_pixel(xx, yy, color);
                }
            }
        }
    }

    /// Draw one bitmap glyph inside a `cell_w` by `cell_h` box.
    pub fn draw_glyph(&mut self, ch: char, x: f32, y: f32, cell_w: f32, cell_h: f32, color: Color) {
        let glyph = font::glyph(ch);
        let glyph_w = cell_w * 0.82;
        let start_x = x + (cell_w - glyph_w) / 2.0;
        for (row_idx, row) in glyph.iter().enumerate() {
            for (col_idx, cell) in row.chars().enumerate() {
                if cell != '#' {
                    continue;
                }
                let px = start_x + col_idx as f32 * glyph_w / 5.0;
                let py = y + row_idx as f32 * cell_h / 7.0;
                let pw = (glyph_w / 5.0).ceil().max(1.0);
                let ph = (cell_h / 7.0).ceil().max(1.0);
                self.fill_rect(px, py, pw, ph, color);
            }
        }
    }

    /// Draw a run of text with an explicitly supplied advance for each
    /// Unicode scalar.  Combining marks are skipped by callers that have
    /// already accounted for them in the width calculation.
    pub fn draw_text(&mut self, text: &str, x: f32, y: f32, advance: f32, glyph_h: f32, color: Color) {
        let mut cursor = x;
        for ch in text.chars() {
            if font::is_combining(ch) {
                continue;
            }
            if ch != ' ' && ch != '\t' {
                self.draw_glyph(ch, cursor, y, advance, glyph_h, color);
            }
            cursor += advance;
        }
    }

    pub fn draw_image(&mut self, img: &crate::png::DecodedImage, x: f32, y: f32, w: f32, h: f32, radius: f32) {
        let x0 = x.floor() as i32;
        let y0 = y.floor() as i32;
        let x1 = (x + w).ceil() as i32;
        let y1 = (y + h).ceil() as i32;
        for yy in y0..y1 {
            for xx in x0..x1 {
                if !Self::rounded_rect_contains(xx as f32 + 0.5, yy as f32 + 0.5, x, y, w, h, radius) {
                    continue;
                }
                let sx = ((xx as f32 + 0.5 - x) / w * img.width as f32).floor() as usize;
                let sy = ((yy as f32 + 0.5 - y) / h * img.height as f32).floor() as usize;
                let sx = sx.min(img.width as usize - 1);
                let sy = sy.min(img.height as usize - 1);
                let idx = (sy * img.width as usize + sx) * 4;
                let color = Color::rgba(img.rgba[idx], img.rgba[idx + 1], img.rgba[idx + 2], img.rgba[idx + 3]);
                self.blend_pixel(xx, yy, color);
            }
        }
    }
}
