fn language_from_shebang(first_line: &str) -> &'static str {
    let line = first_line.trim();
    if !line.starts_with("#!") {
        return "text";
    }
    let lower = line.to_ascii_lowercase();
    if lower.contains("python") {
        "python"
    } else if lower.contains("node") || lower.contains("deno") || lower.contains("bun") {
        "javascript"
    } else if lower.contains("ruby") {
        "ruby"
    } else if lower.contains("perl") {
        "perl"
    } else if lower.contains("php") {
        "php"
    } else if lower.contains("lua") {
        "lua"
    } else if lower.contains("bash") || lower.contains("/sh") || lower.ends_with(" sh") {
        "bash"
    } else if lower.contains("zsh") {
        "zsh"
    } else if lower.contains("fish") {
        "fish"
    } else {
        "text"
    }
}

fn determine_language(code: &CodeContent) -> Result<&'static str, String> {
    if let Some(language) = &code.language {
        return Ok(language_from_token(language));
    }
    if let Some(file_path) = &code.file_path {
        if let Some(language) = recognized_syntax(file_path) {
            return Ok(language);
        }
        let file = std::fs::File::open(file_path)
            .map_err(|_| format!("No such file {}", file_path))?;
        let mut reader = std::io::BufReader::new(file);
        let mut first_line = String::new();
        reader
            .read_line(&mut first_line)
            .map_err(|_| format!("No such file {}", file_path))?;
        return Ok(language_from_shebang(&first_line));
    }
    Ok("text")
}

fn expand_tabs(s: &str) -> String {
    s.replace('\t', "  ")
}

fn prepare_display_lines(code: &str) -> Vec<String> {
    // `str::lines` supplies the line semantics used by the range and
    // highlight validation.  Rendering then splits bare carriage
    // returns visually, drops a single trailing empty line, replaces
    // tabs with two spaces, and removes the indentation common to the
    // remaining lines (unless a blank line suppresses that removal).
    let mut lines: Vec<String> = Vec::new();
    for line in code.lines() {
        if line.contains('\r') {
            for part in line.split('\r') {
                lines.push(part.to_string());
            }
        } else {
            lines.push(line.to_string());
        }
    }
    if lines.last().map(|l| l.is_empty()).unwrap_or(false) {
        lines.pop();
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    let mut lines: Vec<String> = lines.into_iter().map(|l| expand_tabs(&l)).collect();

    let has_blank = lines.iter().any(|l| l.trim().is_empty());
    let min_indent = if lines.len() > 1 && has_blank {
        0
    } else {
        lines
            .iter()
            .map(|l| l.chars().take_while(|c| *c == ' ').count())
            .min()
            .unwrap_or(0)
    };
    if min_indent > 0 {
        for line in &mut lines {
            let remove = line.chars().take(min_indent).map(|c| c.len_utf8()).sum::<usize>();
            *line = line[remove.min(line.len())..].to_string();
        }
    }
    lines
}

fn char_advance(ch: char) -> f32 {
    if font::is_combining(ch) {
        0.0
    } else if ('\u{1f000}'..='\u{1faff}').contains(&ch) || ('\u{2600}'..='\u{27bf}').contains(&ch) && ch > '\u{26ff}' {
        13.04
    } else if ('\u{2600}'..='\u{26ff}').contains(&ch) {
        11.21
    } else {
        CODE_ADVANCE
    }
}

fn text_width(s: &str) -> f32 {
    s.chars().map(char_advance).sum()
}

fn single_line(s: &str) -> String {
    s.chars().map(|c| if c == '\n' || c == '\r' { ' ' } else { c }).collect()
}

struct PreparedCode {
    lines: Vec<String>,
    language: &'static str,
}

enum Prepared {
    Code(PreparedCode),
    Image(DecodedImage),
    Command(Vec<(String, Vec<String>)>),
}

fn prepare(spec: &SnapshotSpec) -> Result<Prepared, String> {
    check_syntax_paths(&spec.syntax_paths)?;
    if spec.theme != "candy" {
        return Err(format!("Cannot find {} theme", spec.theme));
    }
    match &spec.content {
        RenderContent::Code(code) => {
            let language = determine_language(code)?;
            Ok(Prepared::Code(PreparedCode {
                lines: prepare_display_lines(&code.content),
                language,
            }))
        }
        RenderContent::Image(bytes) => Ok(Prepared::Image(png::decode_png(bytes)?)),
        RenderContent::Command(commands) => {
            let mut out = Vec::new();
            for (command, output) in commands {
                crate::components::command_line::command_line_header::first_command_token(command);
                let lines = prepare_display_lines(output);
                out.push((command.clone(), lines));
            }
            Ok(Prepared::Command(out))
        }
    }
}

fn header_height(spec: &SnapshotSpec) -> f32 {
    let mut h = 0.0;
    if spec.window.mac_window_bar {
        h += 24.0;
    } else if spec.title.is_some() {
        h += 14.0;
    }
    if spec.breadcrumbs.is_some() {
        h += 15.0;
    }
    h
}

fn code_gutter_width(code: &CodeContent, line_count: usize) -> f32 {
    match code.start_line_number {
        None => 0.0,
        Some(start) => {
            let last = start.wrapping_add(line_count.saturating_sub(1) as u32);
            let digits = last.to_string().len() as f32;
            digits * 9.0 + 10.0
        }
    }
}

fn window_size(spec: &SnapshotSpec, prepared: &Prepared) -> (f32, f32) {
    match prepared {
        Prepared::Image(img) => (img.width as f32, img.height as f32),
        Prepared::Code(code) => {
            let code_content = match &spec.content {
                RenderContent::Code(c) => c,
                _ => unreachable!(),
            };
            let gutter = code_gutter_width(code_content, code.lines.len());
            let mut required = 354.0f32;
            let max_line_width = code.lines.iter().map(|l| text_width(l)).fold(0.0f32, f32::max);
            required = required.max(32.0 + gutter + max_line_width);
            if let Some(bc) = &spec.breadcrumbs {
                required = required.max(32.0 + 8.0 * bc.file_path.chars().count() as f32);
            }
            if let Some(title) = &spec.title {
                let title_chars = title.chars().count() as f32;
                let title_required = if spec.window.mac_window_bar {
                    94.0 + 6.0 * title_chars
                } else {
                    32.0 + 6.0 * title_chars
                };
                required = required.max(title_required);
            }
            let height = header_height(spec) + 30.0 + 18.0 * code.lines.len() as f32;
            (required, height)
        }
        Prepared::Command(blocks) => {
            let mut required = 354.0f32;
            let mut content_height = 30.0f32;
            let prompt_chars = spec.command_output_config.prompt.chars().count() as f32;
            for (command, output) in blocks {
                let header_width = text_width(command) + (prompt_chars + 1.0) * CODE_ADVANCE;
                required = required.max(32.0 + header_width);
                let out_width = output.iter().map(|l| text_width(l)).fold(0.0f32, f32::max);
                required = required.max(32.0 + out_width);
                content_height += 20.0 * (1 + output.len()) as f32;
            }
            if let Some(title) = &spec.title {
                let title_chars = title.chars().count() as f32;
                let title_required = if spec.window.mac_window_bar {
                    94.0 + 6.0 * title_chars
                } else {
                    32.0 + 6.0 * title_chars
                };
                required = required.max(title_required);
            }
            // Breadcrumbs/title header behavior follows the code window,
            // although breadcrumbs themselves are only supplied by the
            // CLI for code content.
            let header = {
                let mut h = 0.0;
                if spec.window.mac_window_bar {
                    h += 24.0;
                } else if spec.title.is_some() {
                    h += 14.0;
                }
                h
            };
            (required, header + content_height)
        }
    }
}

fn gradient_color_at(stops: &[(f32, Color)], t: f32) -> Color {
    if stops.is_empty() {
        return Color::rgb(0, 0, 0);
    }
    if stops.len() == 1 || t <= stops[0].0 {
        return stops[0].1;
    }
    if t >= stops[stops.len() - 1].0 {
        return stops[stops.len() - 1].1;
    }
    for pair in stops.windows(2) {
        let (p0, c0) = pair[0];
        let (p1, c1) = pair[1];
        if t >= p0 && t <= p1 {
            let f = if (p1 - p0).abs() < f32::EPSILON { 0.0 } else { (t - p0) / (p1 - p0) };
            return Color::rgba(
                (c0.r as f32 + (c1.r as f32 - c0.r as f32) * f).round() as u8,
                (c0.g as f32 + (c1.g as f32 - c0.g as f32) * f).round() as u8,
                (c0.b as f32 + (c1.b as f32 - c0.b as f32) * f).round() as u8,
                (c0.a as f32 + (c1.a as f32 - c0.a as f32) * f).round() as u8,
            );
        }
    }
    stops[stops.len() - 1].1
}

fn draw_background(canvas: &mut Canvas, background: &Background, logical_w: f32, logical_h: f32, scale: f32) {
    match background {
        Background::Color(s) => {
            let color = from_hex(s);
            canvas.fill_whole(color);
        }
        Background::Gradient { start, end, stops } => {
            let parsed = crate::components::background::parse_stops(stops);
            if parsed.len() == 1 {
                canvas.fill_whole(parsed[0].1);
                return;
            }
            let sx = start.x.resolve(logical_w) * scale;
            let sy = start.y.resolve(logical_h) * scale;
            let ex = end.x.resolve(logical_w) * scale;
            let ey = end.y.resolve(logical_h) * scale;
            let dx = ex - sx;
            let dy = ey - sy;
            let denom = dx * dx + dy * dy;
            for y in 0..canvas.height {
                for x in 0..canvas.width {
                    let px = x as f32 + 0.5;
                    let py = y as f32 + 0.5;
                    let t = if denom <= 0.0 {
                        0.0
                    } else {
                        (((px - sx) * dx + (py - sy) * dy) / denom).clamp(0.0, 1.0)
                    };
                    canvas.set_pixel(x as i32, y as i32, gradient_color_at(&parsed, t));
                }
            }
        }
    }
}

fn highlight_color_for_line(highlights: &[HighlightLine], line_1based: u32, parsed: &[(HighlightLine, Color)]) -> Option<Color> {
    let _ = highlights;
    let mut found = None;
    for (hl, color) in parsed {
        let matches = match hl {
            HighlightLine::Single(n, _) => *n == line_1based && *n >= 1,
            HighlightLine::Range(s, e, _) => {
                if *s == 0 || *e == 0 {
                    false
                } else {
                    let lo = (*s).min(*e);
                    let hi = (*s).max(*e);
                    line_1based >= lo && line_1based <= hi
                }
            }
        };
        if matches {
            found = Some(*color);
        }
    }
    found
}

#[derive(Clone, Copy, PartialEq)]
enum TokenKind {
    Default,
    Keyword,
    String,
    Number,
    Comment,
    Type,
    Function,
}

fn token_color(kind: TokenKind) -> Color {
    match kind {
        TokenKind::Default => Color::rgb(0xf8, 0xf8, 0xf2),
        TokenKind::Keyword => Color::rgb(0xff, 0x79, 0xc6),
        TokenKind::String => Color::rgb(0xf1, 0xfa, 0x8c),
        TokenKind::Number => Color::rgb(0xbd, 0x93, 0xf9),
        TokenKind::Comment => Color::rgb(0x62, 0x72, 0xa4),
        TokenKind::Type => Color::rgb(0x8b, 0xe9, 0xfd),
        TokenKind::Function => Color::rgb(0x50, 0xfa, 0x7b),
    }
}

fn keywords_for(language: &str) -> &'static [&'static str] {
    match language {
        "rust" => &["as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum", "extern", "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub", "ref", "return", "self", "Self", "static", "struct", "super", "trait", "true", "type", "unsafe", "use", "where", "while"],
        "python" => &["and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del", "elif", "else", "except", "False", "finally", "for", "from", "global", "if", "import", "in", "is", "lambda", "None", "nonlocal", "not", "or", "pass", "raise", "return", "True", "try", "while", "with", "yield"],
        "javascript" | "typescript" => &["async", "await", "break", "case", "catch", "class", "const", "continue", "default", "delete", "do", "else", "export", "extends", "false", "finally", "for", "from", "function", "if", "import", "in", "instanceof", "let", "new", "null", "of", "return", "super", "switch", "this", "throw", "true", "try", "typeof", "undefined", "var", "while", "yield", "interface", "type", "enum", "implements", "private", "protected", "public", "readonly", "abstract"],
        "c" | "cpp" => &["auto", "bool", "break", "case", "catch", "char", "class", "const", "constexpr", "continue", "default", "delete", "do", "double", "else", "enum", "explicit", "extern", "false", "float", "for", "friend", "if", "inline", "int", "long", "mutable", "namespace", "new", "nullptr", "private", "protected", "public", "return", "short", "signed", "sizeof", "static", "struct", "switch", "template", "this", "throw", "true", "try", "typedef", "typename", "union", "unsigned", "using", "virtual", "void", "volatile", "while"],
        "java" | "kotlin" | "scala" | "csharp" => &["abstract", "boolean", "break", "byte", "case", "catch", "char", "class", "const", "continue", "default", "do", "double", "else", "enum", "extends", "false", "final", "finally", "float", "for", "fun", "if", "implements", "import", "instanceof", "int", "interface", "long", "new", "null", "object", "package", "private", "protected", "public", "return", "short", "static", "super", "switch", "this", "throw", "throws", "true", "try", "val", "var", "void", "when", "while"],
        "go" => &["break", "case", "chan", "const", "continue", "default", "defer", "else", "fallthrough", "false", "for", "func", "go", "goto", "if", "import", "interface", "map", "nil", "package", "range", "return", "select", "struct", "switch", "true", "type", "var"],
        "ruby" => &["alias", "and", "begin", "break", "case", "class", "def", "defined", "do", "else", "elsif", "end", "ensure", "false", "for", "if", "in", "module", "next", "nil", "not", "or", "redo", "rescue", "retry", "return", "self", "super", "then", "true", "undef", "unless", "until", "when", "while", "yield", "require"],
        "bash" | "zsh" | "fish" => &["case", "do", "done", "elif", "else", "esac", "export", "fi", "for", "function", "if", "in", "local", "readonly", "return", "select", "then", "time", "until", "while"],
        "sql" => &["alter", "and", "as", "begin", "by", "commit", "create", "delete", "drop", "from", "group", "having", "in", "index", "insert", "into", "join", "left", "limit", "not", "null", "offset", "on", "or", "order", "primary", "right", "rollback", "select", "set", "table", "transaction", "union", "update", "values", "where"],
        _ => &["and", "as", "break", "case", "catch", "class", "const", "continue", "default", "do", "else", "enum", "export", "extends", "false", "finally", "for", "from", "function", "if", "import", "in", "let", "new", "null", "private", "protected", "public", "return", "static", "struct", "switch", "this", "throw", "true", "try", "type", "var", "while"],
    }
}

fn draw_code_line(canvas: &mut Canvas, line: &str, x: f32, y: f32, scale: f32, language: &str, in_block_comment: &mut bool, in_triple: &mut Option<char>) {
    let advance = CODE_ADVANCE * scale;
    let glyph_h = 9.0 * scale;
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0usize;
    let mut cursor = x;
    let line_comment = match language {
        "python" | "ruby" | "bash" | "zsh" | "fish" | "perl" | "r" | "yaml" | "toml" | "make" | "docker" | "ini" => Some("#"),
        "sql" | "lua" | "haskell" => Some("--"),
        "text" | "markdown" | "json" => None,
        _ => Some("//"),
    };
    let draw_segment = |canvas: &mut Canvas, text: &str, cursor: &mut f32, kind: TokenKind| {
        canvas.draw_text(text, *cursor, y, advance, glyph_h, token_color(kind));
        *cursor += text_width(text) * scale;
    };

    if *in_block_comment {
        if let Some(end) = line.find("*/") {
            let segment = &line[..end + 2];
            draw_segment(canvas, segment, &mut cursor, TokenKind::Comment);
            i = chars.iter().take_while(|_| false).count(); // placeholder, recalculated below
            // Convert byte position to char index.
            i = line[..end + 2].chars().count();
            *in_block_comment = false;
        } else {
            draw_segment(canvas, line, &mut cursor, TokenKind::Comment);
            return;
        }
    }
    if let Some(q) = *in_triple {
        let closing = if q == '"' { "\"\"\"" } else { "'''" };
        if let Some(end) = line.find(closing) {
            let segment = &line[..end + 3];
            draw_segment(canvas, segment, &mut cursor, TokenKind::String);
            i = line[..end + 3].chars().count();
            *in_triple = None;
        } else {
            draw_segment(canvas, line, &mut cursor, TokenKind::String);
            return;
        }
    }

    while i < chars.len() {
        let rest: String = chars[i..].iter().collect();
        // Triple-quoted strings in Python.
        if language == "python" && (rest.starts_with("\"\"\"") || rest.starts_with("'''")) {
            let quote = chars[i];
            let closing = if quote == '"' { "\"\"\"" } else { "'''" };
            if let Some(rel) = rest[3..].find(closing) {
                let segment = &rest[..3 + rel + 3];
                draw_segment(canvas, segment, &mut cursor, TokenKind::String);
                i += segment.chars().count();
            } else {
                draw_segment(canvas, &rest, &mut cursor, TokenKind::String);
                *in_triple = Some(quote);
                return;
            }
            continue;
        }
        if matches!(language, "html" | "xml") && rest.starts_with("<!--") {
            if let Some(rel) = rest.find("-->") {
                let segment = &rest[..rel + 3];
                draw_segment(canvas, segment, &mut cursor, TokenKind::Comment);
                i += segment.chars().count();
                continue;
            }
        }
        if !matches!(language, "python" | "ruby" | "bash" | "zsh" | "fish" | "text" | "markdown" | "html" | "xml") && rest.starts_with("/*") {
            if let Some(rel) = rest[2..].find("*/") {
                let segment = &rest[..2 + rel + 2];
                draw_segment(canvas, segment, &mut cursor, TokenKind::Comment);
                i += segment.chars().count();
            } else {
                draw_segment(canvas, &rest, &mut cursor, TokenKind::Comment);
                *in_block_comment = true;
                return;
            }
            continue;
        }
        if let Some(marker) = line_comment {
            if rest.starts_with(marker) {
                // Avoid treating a Rust attribute/# in a string-like
                // position too aggressively; the languages using # are
                // selected above.
                draw_segment(canvas, &rest, &mut cursor, TokenKind::Comment);
                return;
            }
        }
        let ch = chars[i];
        if ch == '"' || ch == '\'' || ch == '`' {
            let mut j = i + 1;
            while j < chars.len() {
                if chars[j] == '\\' && language != "python" {
                    j += 2;
                    continue;
                }
                if chars[j] == '\\' && language == "python" {
                    j += 2;
                    continue;
                }
                if chars[j] == ch {
                    j += 1;
                    break;
                }
                j += 1;
            }
            let j = j.min(chars.len());
            let segment: String = chars[i..j].iter().collect();
            draw_segment(canvas, &segment, &mut cursor, TokenKind::String);
            i = j;
            continue;
        }
        if ch.is_ascii_digit() {
            let mut j = i;
            while j < chars.len() && (chars[j].is_ascii_alphanumeric() || matches!(chars[j], '.' | '_' | 'x' | 'X')) {
                j += 1;
            }
            let segment: String = chars[i..j].iter().collect();
            draw_segment(canvas, &segment, &mut cursor, TokenKind::Number);
            i = j;
            continue;
        }
        if ch == '_' || ch.is_alphabetic() {
            let mut j = i;
            while j < chars.len() && (chars[j] == '_' || chars[j].is_alphanumeric()) {
                j += 1;
            }
            let word: String = chars[i..j].iter().collect();
            let next_non_space = chars[j..].iter().find(|c| **c != ' ').copied();
            let kind = if keywords_for(language).contains(&word.as_str()) {
                TokenKind::Keyword
            } else if next_non_space == Some('(') || (j < chars.len() && chars[j] == '!') {
                TokenKind::Function
            } else if word.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) {
                TokenKind::Type
            } else if word.len() > 1 && word.chars().all(|c| c.is_uppercase() || c == '_' || c.is_ascii_digit()) {
                TokenKind::Number
            } else {
                TokenKind::Default
            };
            draw_segment(canvas, &word, &mut cursor, kind);
            i = j;
            continue;
        }
        // One punctuation / space character.
        let segment: String = chars[i..i + 1].iter().collect();
        draw_segment(canvas, &segment, &mut cursor, TokenKind::Default);
        i += 1;
    }
}

fn draw_command_header(canvas: &mut Canvas, command: &str, cfg: &CommandOutputConfig, x: f32, y: f32, scale: f32) {
    let advance = CODE_ADVANCE * scale;
    let glyph_h = 9.0 * scale;
    let prompt_color = from_hex(&cfg.prompt_color);
    let command_color = from_hex(&cfg.command_color);
    let string_color = from_hex(&cfg.string_arg_color);
    canvas.draw_text(&cfg.prompt, x, y, advance, glyph_h, prompt_color);
    let mut cursor = x + (cfg.prompt.chars().count() as f32 + 1.0) * advance;
    // Color the first whitespace-delimited word as the command, quoted
    // spans as string arguments, and the remainder as ordinary command
    // text.  The displayed string itself is the original command.
    let chars: Vec<char> = command.chars().collect();
    let mut i = 0usize;
    let mut first_word_done = false;
    while i < chars.len() {
        let ch = chars[i];
        if ch == '"' || ch == '\'' {
            let mut j = i + 1;
            while j < chars.len() && chars[j] != ch {
                if chars[j] == '\\' {
                    j += 1;
                }
                j += 1;
            }
            if j < chars.len() {
                j += 1;
            }
            let segment: String = chars[i..j.min(chars.len())].iter().collect();
            canvas.draw_text(&segment, cursor, y, advance, glyph_h, string_color);
            cursor += text_width(&segment) * scale;
            i = j;
            first_word_done = true;
            continue;
        }
        if ch.is_whitespace() {
            let segment: String = chars[i..i + 1].iter().collect();
            cursor += text_width(&segment) * scale;
            i += 1;
            if i > 0 {
                first_word_done = true;
            }
            continue;
        }
        let mut j = i;
        while j < chars.len() && !chars[j].is_whitespace() && chars[j] != '"' && chars[j] != '\'' {
            j += 1;
        }
        let segment: String = chars[i..j].iter().collect();
        let color = if !first_word_done {
            Color::rgb(0x98, 0xc3, 0x79)
        } else {
            command_color
        };
        // The default prompt/command colors in a user supplied config
        // still need to be visible as the command text, so use the
        // configured command color for non-initial words.  For the
        // initial word, the reference defaults produce a green word;
        // when cfg is the internally created default our command_color
        // is light, hence the explicit green in that path is confined
        // to a comparison with its default value in practice by the
        // caller passing its own config colors through below.
        let color = if !first_word_done && cfg.command_color.eq_ignore_ascii_case("#f8f8f2") {
            color
        } else if !first_word_done {
            command_color
        } else {
            color
        };
        canvas.draw_text(&segment, cursor, y, advance, glyph_h, color);
        cursor += text_width(&segment) * scale;
        first_word_done = true;
        i = j;
    }
}

pub fn render_snapshot(spec: &SnapshotSpec) -> Result<Vec<u8>, String> {
    let prepared = prepare(spec)?;
    let scale = spec.scale_factor as f32;
    let (window_w_logical, window_h_logical) = window_size(spec, &prepared);
    let window_w_px = (window_w_logical * scale).ceil();
    let window_h_px = (window_h_logical * scale).ceil();
    let watermark_extra = if spec.watermark.is_some() && spec.window.margin_y >= 82.0 {
        72.0
    } else {
        0.0
    };
    let canvas_w_f = (window_w_px + 2.0 * spec.window.margin_x * scale).floor();
    let canvas_h_f = (window_h_px + (2.0 * spec.window.margin_y + watermark_extra) * scale).floor();
    if !canvas_w_f.is_finite() || !canvas_h_f.is_finite() || canvas_w_f <= 0.0 || canvas_h_f <= 0.0 {
        crate::components::container::create_surface(canvas_w_f, canvas_h_f);
    }
    // Guard against absurd allocations from extreme scale/margin
    // combinations in the same spirit as a raster surface failing to
    // be created (the call above handles the non-positive case).
    let canvas_w = canvas_w_f as usize;
    let canvas_h = canvas_h_f as usize;
    let mut canvas = Canvas::new(canvas_w, canvas_h);

    let logical_w = window_w_logical + 2.0 * spec.window.margin_x;
    let logical_h = window_h_logical + 2.0 * spec.window.margin_y + watermark_extra;
    draw_background(&mut canvas, &spec.background, logical_w, logical_h, scale);

    let wx = spec.window.margin_x * scale;
    let wy = spec.window.margin_y * scale;
    let ww = window_w_px;
    let wh = window_h_px;
    let radius = spec.window.radius * scale;

    let shadow_color = from_hex(&spec.window.shadow_color);
    canvas.shadow_rounded_rect(wx, wy, ww, wh, radius, spec.window.shadow_radius * scale, shadow_color);

    // Window body (also the backdrop for image content).
    canvas.fill_rounded_rect(wx, wy, ww, wh, radius, Color::rgb(0x28, 0x2a, 0x36));

    match &prepared {
        Prepared::Image(img) => {
            canvas.draw_image(img, wx, wy, ww, wh, radius);
        }
        Prepared::Code(prepared_code) => {
            let code = match &spec.content {
                RenderContent::Code(c) => c,
                _ => unreachable!(),
            };
            // Parse all highlight colors even if their line is outside
            // the displayed range.
            let parsed_highlights: Vec<(HighlightLine, Color)> = code
                .highlight_lines
                .iter()
                .map(|hl| {
                    let color = match hl {
                        HighlightLine::Single(_, c) => from_hex(c),
                        HighlightLine::Range(_, _, c) => from_hex(c),
                    };
                    (hl.clone(), color)
                })
                .collect();

            draw_window_chrome(&mut canvas, spec, wx, wy, ww, scale);

            let header_h = header_height(spec) * scale;
            let content_top = wy + header_h;
            let line_box_h = 18.0 * scale;
            let first_line_y = content_top + 14.0 * scale;

            if let Some(bc) = &spec.breadcrumbs {
                let color = from_hex(&bc.color);
                let text = single_line(&bc.file_path.replace('/', &bc.separator));
                let bc_top = wy + (if spec.window.mac_window_bar { 24.0 } else if spec.title.is_some() { 14.0 } else { 0.0 }) * scale;
                canvas.draw_text(&text, wx + 17.0 * scale, bc_top + 7.0 * scale, 8.0 * scale, 8.0 * scale, color);
            }

            // Highlight rectangles, including a possible line just
            // below the final displayed line.
            let max_hl_line = parsed_highlights
                .iter()
                .map(|(hl, _)| match hl {
                    HighlightLine::Single(n, _) => *n,
                    HighlightLine::Range(s, e, _) => (*s).max(*e),
                })
                .max()
                .unwrap_or(0);
            let upto = (prepared_code.lines.len() as u32 + 1).min(max_hl_line);
            for idx in 1..=upto {
                if let Some(color) = highlight_color_for_line(&code.highlight_lines, idx, &parsed_highlights) {
                    let y = first_line_y + (idx - 1) as f32 * line_box_h;
                    if y < wy + wh {
                        let h = line_box_h.min(wy + wh - y);
                        canvas.fill_rect(wx + scale, y, ww - 2.0 * scale, h, color);
                    }
                }
            }

            let gutter = code_gutter_width(code, prepared_code.lines.len());
            let line_number_color = if code.start_line_number.is_some() {
                Some(from_hex(&spec.line_number_color))
            } else {
                None
            };
            let max_digits = code.start_line_number.map(|start| {
                start
                    .wrapping_add(prepared_code.lines.len().saturating_sub(1) as u32)
                    .to_string()
                    .len()
            });
            let mut in_block_comment = false;
            let mut in_triple: Option<char> = None;
            for (idx, line) in prepared_code.lines.iter().enumerate() {
                let line_y = first_line_y + idx as f32 * line_box_h;
                let text_y = line_y + 4.0 * scale;
                let mut code_x = wx + 16.0 * scale;
                if let (Some(start), Some(color), Some(digits)) = (code.start_line_number, line_number_color, max_digits) {
                    let number = start.wrapping_add(idx as u32).to_string();
                    let offset = (digits - number.len()) as f32 * 9.0 * scale;
                    canvas.draw_text(&number, code_x + offset, text_y, 9.0 * scale, 9.0 * scale, color);
                    code_x += gutter * scale;
                }
                draw_code_line(
                    &mut canvas,
                    line,
                    code_x,
                    text_y,
                    scale,
                    prepared_code.language,
                    &mut in_block_comment,
                    &mut in_triple,
                );
            }
        }
        Prepared::Command(blocks) => {
            // Touch the configured colors once even for an empty list
            // of commands is not necessary; per-block drawing parses
            // them when a block exists.
            draw_window_chrome(&mut canvas, spec, wx, wy, ww, scale);
            let header_h = if spec.window.mac_window_bar {
                24.0 * scale
            } else if spec.title.is_some() {
                14.0 * scale
            } else {
                0.0
            };
            let mut block_y = wy + header_h + 14.0 * scale;
            let output_color = Color::rgb(0x97, 0x9e, 0xab);
            for (command, output) in blocks {
                draw_command_header(
                    &mut canvas,
                    command,
                    &spec.command_output_config,
                    wx + 16.0 * scale,
                    block_y + 5.0 * scale,
                    scale,
                );
                for (idx, line) in output.iter().enumerate() {
                    let y = block_y + 20.0 * scale + idx as f32 * 20.0 * scale;
                    canvas.draw_text(
                        &expand_tabs(line),
                        wx + 16.0 * scale,
                        y + 5.0 * scale,
                        CODE_ADVANCE * scale,
                        9.0 * scale,
                        output_color,
                    );
                }
                block_y += 20.0 * scale * (1 + output.len()) as f32;
            }
        }
    }

    // Border is drawn over the window and image edges.
    let border_color = from_hex(&spec.window.border_color);
    canvas.stroke_rounded_rect(wx, wy, ww, wh, radius, scale.max(1.0), border_color);

    if let Some(watermark) = &spec.watermark {
        if spec.window.margin_y >= 82.0 {
            let color = from_hex(&watermark.color);
            let text = single_line(&watermark.content);
            let advance = 15.0 * scale;
            let text_w = text.chars().count() as f32 * advance;
            let x = (canvas_w as f32 - text_w) / 2.0;
            let y = wy + wh + 50.0 * scale;
            canvas.draw_text(&text, x, y, advance, 30.0 * scale, color);
        }
    }

    Ok(png::encode_png(canvas_w as u32, canvas_h as u32, &canvas.pixels))
}

fn draw_window_chrome(canvas: &mut Canvas, spec: &SnapshotSpec, wx: f32, wy: f32, ww: f32, scale: f32) {
    if spec.window.mac_window_bar {
        let colors = [
            Color::rgb(0xff, 0x5e, 0x57),
            Color::rgb(0xff, 0xba, 0x2e),
            Color::rgb(0x2b, 0xc8, 0x41),
        ];
        for (i, color) in colors.iter().enumerate() {
            let cx = wx + (21.5 + i as f32 * 16.0) * scale;
            let cy = wy + 21.5 * scale;
            canvas.fill_circle(cx, cy, 5.0 * scale, *color);
        }
    }
    if let Some(title) = &spec.title {
        let color = from_hex(&spec.window.title_color);
        let text = single_line(title);
        let advance = 6.0 * scale;
        let text_w = text.chars().count() as f32 * advance;
        let x = wx + (ww - text_w) / 2.0;
        let y = if spec.window.mac_window_bar {
            wy + 8.0 * scale
        } else {
            wy + 3.0 * scale
        };
        canvas.draw_text(&text, x, y, advance, 9.0 * scale, color);
    }
}
