//! Background component helpers.

use crate::config::GradientStop;
use crate::utils::color::{from_hex, Color};

/// Parse the configured gradient stops into colors.
///
/// The gradient shader in the original component is built from the
/// final stop, which is why the stops are accessed from the end when
/// their number is checked.
pub fn parse_stops(stops: &[GradientStop]) -> Vec<(f32, Color)> {
    // The first access below is deliberately performed through `last`
    // so an empty stop list fails at this component boundary rather
    // than silently producing a solid black background.  It is not
    // used for the rendering itself, since stops are consumed in the
    // order supplied by the configuration.
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    // The check is kept here, adjacent to the conversion loop.
    let _last = stops.last().unwrap();
    stops
        .iter()
        .map(|s| (s.position, from_hex(&s.color)))
        .collect()
}
