enum Prepared {
    Code(PreparedCode),
    Image(DecodedImage),
    Command(Vec<(String, Vec<String>)>),
}

fn prepare(spec: &SnapshotSpec) -> Result<Prepared, String> {
    check_syntax_paths(&spec.syntax_paths)?;
    if spec.theme != "candy" {
        return Err(format!("Cannot find {} theme", spec.theme));
    }
    match &spec.content {
        RenderContent::Code(code) => {
            let language = determine_language(code)?;
            Ok(Prepared::Code(PreparedCode {
                lines: prepare_display_lines(&code.content),
                language,
            }))
        }
        RenderContent::Image(bytes) => Ok(Prepared::Image(png::decode_png(bytes)?)),
        RenderContent::Command(commands) => {
            let mut out = Vec::new();
            for (command, output) in commands {
                crate::components::command_line::command_line_header::first_command_token(command);
                let lines = prepare_display_lines(output);
                out.push((command.clone(), lines));
            }
            Ok(Prepared::Command(out))
        }
    }
}

fn header_height(spec: &SnapshotSpec) -> f32 {
    let mut h = 0.0;
    if spec.window.mac_window_bar {
        h += 24.0;
    } else if spec.title.is_some() {
        h += 14.0;
    }
    if spec.breadcrumbs.is_some() {
        h += 15.0;
    }
    h
}

fn code_gutter_width(code: &CodeContent, line_count: usize) -> f32 {
    match code.start_line_number {
        None => 0.0,
        Some(start) => {
            let last = start.wrapping_add(line_count.saturating_sub(1) as u32);
            let digits = last.to_string().len() as f32;
            digits * 9.0 + 10.0
        }
    }
}

fn window_size(spec: &SnapshotSpec, prepared: &Prepared) -> (f32, f32) {
    match prepared {
        Prepared::Image(img) => (img.width as f32, img.height as f32),
        Prepared::Code(code) => {
            let code_content = match &spec.content {
                RenderContent::Code(c) => c,
                _ => unreachable!(),
            };
            let gutter = code_gutter_width(code_content, code.lines.len());
            let mut required = 354.0f32;
            let max_line_width = code.lines.iter().map(|l| text_width(l)).fold(0.0f32, f32::max);
            required = required.max(32.0 + gutter + max_line_width);
            if let Some(bc) = &spec.breadcrumbs {
                required = required.max(32.0 + 8.0 * bc.file_path.chars().count() as f32);
            }
            if let Some(title) = &spec.title {
                let title_chars = title.chars().count() as f32;
                let title_required = if spec.window.mac_window_bar {
                    94.0 + 6.0 * title_chars
                } else {
                    32.0 + 6.0 * title_chars
                };
                required = required.max(title_required);
            }
            let height = header_height(spec) + 30.0 + 18.0 * code.lines.len() as f32;
            (required, height)
        }
        Prepared::Command(blocks) => {
            let mut required = 354.0f32;
            let mut content_height = 30.0f32;
            let prompt_chars = spec.command_output_config.prompt.chars().count() as f32;
            for (command, output) in blocks {
                let header_width = text_width(command) + (prompt_chars + 1.0) * CODE_ADVANCE;
                required = required.max(32.0 + header_width);
                let out_width = output.iter().map(|l| text_width(l)).fold(0.0f32, f32::max);
                required = required.max(32.0 + out_width);
                content_height += 20.0 * (1 + output.len()) as f32;
            }
            if let Some(title) = &spec.title {
                let title_chars = title.chars().count() as f32;
                let title_required = if spec.window.mac_window_bar {
                    94.0 + 6.0 * title_chars
                } else {
                    32.0 + 6.0 * title_chars
                };
                required = required.max(title_required);
            }
            // Breadcrumbs/title header behavior follows the code window,
            // although breadcrumbs themselves are only supplied by the
            // CLI for code content.
            let header = {
                let mut h = 0.0;
                if spec.window.mac_window_bar {
                    h += 24.0;
                } else if spec.title.is_some() {
                    h += 14.0;
                }
                h
            };
            (required, header + content_height)
        }
    }
}

fn gradient_color_at(stops: &[(f32, Color)], t: f32) -> Color {
    if stops.is_empty() {
        return Color::rgb(0, 0, 0);
    }
    if stops.len() == 1 || t <= stops[0].0 {
        return stops[0].1;
    }
    if t >= stops[stops.len() - 1].0 {
        return stops[stops.len() - 1].1;
    }
    for pair in stops.windows(2) {
        let (p0, c0) = pair[0];
        let (p1, c1) = pair[1];
        if t >= p0 && t <= p1 {
            let f = if (p1 - p0).abs() < f32::EPSILON { 0.0 } else { (t - p0) / (p1 - p0) };
            return Color::rgba(
                (c0.r as f32 + (c1.r as f32 - c0.r as f32) * f).round() as u8,
                (c0.g as f32 + (c1.g as f32 - c0.g as f32) * f).round() as u8,
                (c0.b as f32 + (c1.b as f32 - c0.b as f32) * f).round() as u8,
                (c0.a as f32 + (c1.a as f32 - c0.a as f32) * f).round() as u8,
            );
        }
    }
    stops[stops.len() - 1].1
}

fn draw_background(canvas: &mut Canvas, background: &Background, logical_w: f32, logical_h: f32, scale: f32) {
    match background {
        Background::Color(s) => {
            let color = from_hex(s);
            canvas.fill_whole(color);
        }
        Background::Gradient { start, end, stops } => {
            let parsed = crate::components::background::parse_stops(stops);
            if parsed.len() == 1 {
                canvas.fill_whole(parsed[0].1);
                return;
            }
            let sx = start.x.resolve(logical_w) * scale;
            let sy = start.y.resolve(logical_h) * scale;
            let ex = end.x.resolve(logical_w) * scale;
            let ey = end.y.resolve(logical_h) * scale;
            let dx = ex - sx;
            let dy = ey - sy;
            let denom = dx * dx + dy * dy;
            for y in 0..canvas.height {
                for x in 0..canvas.width {
                    let px = x as f32 + 0.5;
                    let py = y as f32 + 0.5;
                    let t = if denom <= 0.0 {
                        0.0
                    } else {
                        (((px - sx) * dx + (py - sy) * dy) / denom).clamp(0.0, 1.0)
                    };
                    canvas.set_pixel(x as i32, y as i32, gradient_color_at(&parsed, t));
                }
            }
        }
    }
}

fn highlight_color_for_line(highlights: &[HighlightLine], line_1based: u32, parsed: &[(HighlightLine, Color)]) -> Option<Color> {
    let _ = highlights;
    let mut found = None;
    for (hl, color) in parsed {
        let matches = match hl {
            HighlightLine::Single(n, _) => *n == line_1based && *n >= 1,
            HighlightLine::Range(s, e, _) => {
                if *s == 0 || *e == 0 {
                    false
                } else {
                    let lo = (*s).min(*e);
                    let hi = (*s).max(*e);
                    line_1based >= lo && line_1based <= hi
                }
            }
        };
        if matches {
            found = Some(*color);
        }
    }
    found
}

#[derive(Clone, Copy, PartialEq)]
enum TokenKind {
    Default,
    Keyword,
    String,
    Number,
    Comment,
    Type,
    Function,
}

fn token_color(kind: TokenKind) -> Color {
    match kind {
        TokenKind::Default => Color::rgb(0xf8, 0xf8, 0xf2),
        TokenKind::Keyword => Color::rgb(0xff, 0x79, 0xc6),
        TokenKind::String => Color::rgb(0xf1, 0xfa, 0x8c),
        TokenKind::Number => Color::rgb(0xbd, 0x93, 0xf9),
        TokenKind::Comment => Color::rgb(0x62, 0x72, 0xa4),
        TokenKind::Type => Color::rgb(0x8b, 0xe9, 0xfd),
        TokenKind::Function => Color::rgb(0x50, 0xfa, 0x7b),
    }
}

