fn draw_code_line(canvas: &mut Canvas, line: &str, x: f32, y: f32, scale: f32, language: &str, in_block_comment: &mut bool, in_triple: &mut Option<char>) {
    let advance = CODE_ADVANCE * scale;
    let glyph_h = 9.0 * scale;
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0usize;
    let mut cursor = x;
    let line_comment = match language {
        "python" | "ruby" | "bash" | "zsh" | "fish" | "perl" | "r" | "yaml" | "toml" | "make" | "docker" | "ini" => Some("#"),
        "sql" | "lua" | "haskell" => Some("--"),
        "text" | "markdown" | "json" => None,
        _ => Some("//"),
    };
    let draw_segment = |canvas: &mut Canvas, text: &str, cursor: &mut f32, kind: TokenKind| {
        canvas.draw_text(text, *cursor, y, advance, glyph_h, token_color(kind));
        *cursor += text_width(text) * scale;
    };

    if *in_block_comment {
        if let Some(end) = line.find("*/") {
            let segment = &line[..end + 2];
            draw_segment(canvas, segment, &mut cursor, TokenKind::Comment);
            i = chars.iter().take_while(|_| false).count(); // placeholder, recalculated below
            // Convert byte position to char index.
            i = line[..end + 2].chars().count();
            *in_block_comment = false;
        } else {
            draw_segment(canvas, line, &mut cursor, TokenKind::Comment);
            return;
        }
    }
    if let Some(q) = *in_triple {
        let closing = if q == '"' { "\"\"\"" } else { "'''" };
        if let Some(end) = line.find(closing) {
            let segment = &line[..end + 3];
            draw_segment(canvas, segment, &mut cursor, TokenKind::String);
            i = line[..end + 3].chars().count();
            *in_triple = None;
        } else {
            draw_segment(canvas, line, &mut cursor, TokenKind::String);
            return;
        }
    }

    while i < chars.len() {
        let rest: String = chars[i..].iter().collect();
        // Triple-quoted strings in Python.
        if language == "python" && (rest.starts_with("\"\"\"") || rest.starts_with("'''")) {
            let quote = chars[i];
            let closing = if quote == '"' { "\"\"\"" } else { "'''" };
            if let Some(rel) = rest[3..].find(closing) {
                let segment = &rest[..3 + rel + 3];
                draw_segment(canvas, segment, &mut cursor, TokenKind::String);
                i += segment.chars().count();
            } else {
                draw_segment(canvas, &rest, &mut cursor, TokenKind::String);
                *in_triple = Some(quote);
                return;
            }
            continue;
        }
        if matches!(language, "html" | "xml") && rest.starts_with("<!--") {
            if let Some(rel) = rest.find("-->") {
                let segment = &rest[..rel + 3];
                draw_segment(canvas, segment, &mut cursor, TokenKind::Comment);
                i += segment.chars().count();
                continue;
            }
        }
        if !matches!(language, "python" | "ruby" | "bash" | "zsh" | "fish" | "text" | "markdown" | "html" | "xml") && rest.starts_with("/*") {
            if let Some(rel) = rest[2..].find("*/") {
                let segment = &rest[..2 + rel + 2];
                draw_segment(canvas, segment, &mut cursor, TokenKind::Comment);
                i += segment.chars().count();
            } else {
                draw_segment(canvas, &rest, &mut cursor, TokenKind::Comment);
                *in_block_comment = true;
                return;
            }
            continue;
        }
        if let Some(marker) = line_comment {
            if rest.starts_with(marker) {
                // Avoid treating a Rust attribute/# in a string-like
                // position too aggressively; the languages using # are
                // selected above.
                draw_segment(canvas, &rest, &mut cursor, TokenKind::Comment);
                return;
            }
        }
        let ch = chars[i];
        if ch == '"' || ch == '\'' || ch == '`' {
            let mut j = i + 1;
            while j < chars.len() {
                if chars[j] == '\\' && language != "python" {
                    j += 2;
                    continue;
                }
                if chars[j] == '\\' && language == "python" {
                    j += 2;
                    continue;
                }
                if chars[j] == ch {
                    j += 1;
                    break;
                }
                j += 1;
            }
            let j = j.min(chars.len());
            let segment: String = chars[i..j].iter().collect();
            draw_segment(canvas, &segment, &mut cursor, TokenKind::String);
            i = j;
            continue;
        }
        if ch.is_ascii_digit() {
            let mut j = i;
            while j < chars.len() && (chars[j].is_ascii_alphanumeric() || matches!(chars[j], '.' | '_' | 'x' | 'X')) {
                j += 1;
            }
            let segment: String = chars[i..j].iter().collect();
            draw_segment(canvas, &segment, &mut cursor, TokenKind::Number);
            i = j;
            continue;
        }
        if ch == '_' || ch.is_alphabetic() {
            let mut j = i;
            while j < chars.len() && (chars[j] == '_' || chars[j].is_alphanumeric()) {
                j += 1;
            }
            let word: String = chars[i..j].iter().collect();
            let next_non_space = chars[j..].iter().find(|c| **c != ' ').copied();
            let kind = if keywords_for(language).contains(&word.as_str()) {
                TokenKind::Keyword
            } else if next_non_space == Some('(') || (j < chars.len() && chars[j] == '!') {
                TokenKind::Function
            } else if word.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) {
                TokenKind::Type
            } else if word.len() > 1 && word.chars().all(|c| c.is_uppercase() || c == '_' || c.is_ascii_digit()) {
                TokenKind::Number
            } else {
                TokenKind::Default
            };
            draw_segment(canvas, &word, &mut cursor, kind);
            i = j;
            continue;
        }
        // One punctuation / space character.
        let segment: String = chars[i..i + 1].iter().collect();
        draw_segment(canvas, &segment, &mut cursor, TokenKind::Default);
        i += 1;
    }
}

fn draw_command_header(canvas: &mut Canvas, command: &str, cfg: &CommandOutputConfig, x: f32, y: f32, scale: f32) {
    let advance = CODE_ADVANCE * scale;
    let glyph_h = 9.0 * scale;
    let prompt_color = from_hex(&cfg.prompt_color);
    let command_color = from_hex(&cfg.command_color);
    let string_color = from_hex(&cfg.string_arg_color);
    canvas.draw_text(&cfg.prompt, x, y, advance, glyph_h, prompt_color);
    let mut cursor = x + (cfg.prompt.chars().count() as f32 + 1.0) * advance;
    // Color the first whitespace-delimited word as the command, quoted
    // spans as string arguments, and the remainder as ordinary command
    // text.  The displayed string itself is the original command.
    let chars: Vec<char> = command.chars().collect();
    let mut i = 0usize;
    let mut first_word_done = false;
    while i < chars.len() {
        let ch = chars[i];
        if ch == '"' || ch == '\'' {
            let mut j = i + 1;
            while j < chars.len() && chars[j] != ch {
                if chars[j] == '\\' {
                    j += 1;
                }
                j += 1;
            }
            if j < chars.len() {
                j += 1;
            }
            let segment: String = chars[i..j.min(chars.len())].iter().collect();
            canvas.draw_text(&segment, cursor, y, advance, glyph_h, string_color);
            cursor += text_width(&segment) * scale;
            i = j;
            first_word_done = true;
            continue;
        }
        if ch.is_whitespace() {
            let segment: String = chars[i..i + 1].iter().collect();
            cursor += text_width(&segment) * scale;
            i += 1;
            if i > 0 {
                first_word_done = true;
            }
            continue;
        }
        let mut j = i;
        while j < chars.len() && !chars[j].is_whitespace() && chars[j] != '"' && chars[j] != '\'' {
            j += 1;
        }
        let segment: String = chars[i..j].iter().collect();
        let color = if !first_word_done {
            Color::rgb(0x98, 0xc3, 0x79)
        } else {
            command_color
        };
        // The default prompt/command colors in a user supplied config
        // still need to be visible as the command text, so use the
        // configured command color for non-initial words.  For the
        // initial word, the reference defaults produce a green word;
        // when cfg is the internally created default our command_color
        // is light, hence the explicit green in that path is confined
        // to a comparison with its default value in practice by the
        // caller passing its own config colors through below.
        let color = if !first_word_done && cfg.command_color.eq_ignore_ascii_case("#f8f8f2") {
            color
        } else if !first_word_done {
            command_color
        } else {
            color
        };
        canvas.draw_text(&segment, cursor, y, advance, glyph_h, color);
        cursor += text_width(&segment) * scale;
        first_word_done = true;
        i = j;
    }
}

pub fn render_snapshot(spec: &SnapshotSpec) -> Result<Vec<u8>, String> {
    let prepared = prepare(spec)?;
    let scale = spec.scale_factor as f32;
    let (window_w_logical, window_h_logical) = window_size(spec, &prepared);
    let window_w_px = (window_w_logical * scale).ceil();
    let window_h_px = (window_h_logical * scale).ceil();
    let watermark_extra = if spec.watermark.is_some() && spec.window.margin_y >= 82.0 {
        72.0
    } else {
        0.0
    };
    let canvas_w_f = (window_w_px + 2.0 * spec.window.margin_x * scale).floor();
    let canvas_h_f = (window_h_px + (2.0 * spec.window.margin_y + watermark_extra) * scale).floor();
    if !canvas_w_f.is_finite() || !canvas_h_f.is_finite() || canvas_w_f <= 0.0 || canvas_h_f <= 0.0 {
        crate::components::container::create_surface(canvas_w_f, canvas_h_f);
    }
    // Guard against absurd allocations from extreme scale/margin
    // combinations in the same spirit as a raster surface failing to
    // be created (the call above handles the non-positive case).
    let canvas_w = canvas_w_f as usize;
    let canvas_h = canvas_h_f as usize;
    let mut canvas = Canvas::new(canvas_w, canvas_h);

    let logical_w = window_w_logical + 2.0 * spec.window.margin_x;
    let logical_h = window_h_logical + 2.0 * spec.window.margin_y + watermark_extra;
    draw_background(&mut canvas, &spec.background, logical_w, logical_h, scale);

    let wx = spec.window.margin_x * scale;
    let wy = spec.window.margin_y * scale;
    let ww = window_w_px;
    let wh = window_h_px;
    let radius = spec.window.radius * scale;

    let shadow_color = from_hex(&spec.window.shadow_color);
    canvas.shadow_rounded_rect(wx, wy, ww, wh, radius, spec.window.shadow_radius * scale, shadow_color);

    // Window body (also the backdrop for image content).
    canvas.fill_rounded_rect(wx, wy, ww, wh, radius, Color::rgb(0x28, 0x2a, 0x36));

    match &prepared {
        Prepared::Image(img) => {
            canvas.draw_image(img, wx, wy, ww, wh, radius);
        }
        Prepared::Code(prepared_code) => {
            let code = match &spec.content {
                RenderContent::Code(c) => c,
                _ => unreachable!(),
            };
            // Parse all highlight colors even if their line is outside
            // the displayed range.
            let parsed_highlights: Vec<(HighlightLine, Color)> = code
                .highlight_lines
                .iter()
                .map(|hl| {
                    let color = match hl {
                        HighlightLine::Single(_, c) => from_hex(c),
                        HighlightLine::Range(_, _, c) => from_hex(c),
                    };
                    (hl.clone(), color)
                })
                .collect();

            draw_window_chrome(&mut canvas, spec, wx, wy, ww, scale);

            let header_h = header_height(spec) * scale;
            let content_top = wy + header_h;
            let line_box_h = 18.0 * scale;
            let first_line_y = content_top + 14.0 * scale;

            if let Some(bc) = &spec.breadcrumbs {
                let color = from_hex(&bc.color);
                let text = single_line(&bc.file_path.replace('/', &bc.separator));
                let bc_top = wy + (if spec.window.mac_window_bar { 24.0 } else if spec.title.is_some() { 14.0 } else { 0.0 }) * scale;
                canvas.draw_text(&text, wx + 17.0 * scale, bc_top + 7.0 * scale, 8.0 * scale, 8.0 * scale, color);
            }

            // Highlight rectangles, including a possible line just
            // below the final displayed line.
            let max_hl_line = parsed_highlights
                .iter()
                .map(|(hl, _)| match hl {
                    HighlightLine::Single(n, _) => *n,
                    HighlightLine::Range(s, e, _) => (*s).max(*e),
                })
                .max()
                .unwrap_or(0);
            let upto = (prepared_code.lines.len() as u32 + 1).min(max_hl_line);
            for idx in 1..=upto {
                if let Some(color) = highlight_color_for_line(&code.highlight_lines, idx, &parsed_highlights) {
                    let y = first_line_y + (idx - 1) as f32 * line_box_h;
                    if y < wy + wh {
                        let h = line_box_h.min(wy + wh - y);
                        canvas.fill_rect(wx + scale, y, ww - 2.0 * scale, h, color);
                    }
                }
            }

            let gutter = code_gutter_width(code, prepared_code.lines.len());
            let line_number_color = if code.start_line_number.is_some() {
                Some(from_hex(&spec.line_number_color))
            } else {
                None
            };
            let max_digits = code.start_line_number.map(|start| {
                start
                    .wrapping_add(prepared_code.lines.len().saturating_sub(1) as u32)
                    .to_string()
                    .len()
            });
            let mut in_block_comment = false;
            let mut in_triple: Option<char> = None;
            for (idx, line) in prepared_code.lines.iter().enumerate() {
                let line_y = first_line_y + idx as f32 * line_box_h;
                let text_y = line_y + 4.0 * scale;
                let mut code_x = wx + 16.0 * scale;
                if let (Some(start), Some(color), Some(digits)) = (code.start_line_number, line_number_color, max_digits) {
                    let number = start.wrapping_add(idx as u32).to_string();
                    let offset = (digits - number.len()) as f32 * 9.0 * scale;
                    canvas.draw_text(&number, code_x + offset, text_y, 9.0 * scale, 9.0 * scale, color);
                    code_x += gutter * scale;
                }
                draw_code_line(
                    &mut canvas,
                    line,
                    code_x,
                    text_y,
                    scale,
                    prepared_code.language,
                    &mut in_block_comment,
                    &mut in_triple,
                );
            }
        }
        Prepared::Command(blocks) => {
            // Touch the configured colors once even for an empty list
            // of commands is not necessary; per-block drawing parses
            // them when a block exists.
            draw_window_chrome(&mut canvas, spec, wx, wy, ww, scale);
            let header_h = if spec.window.mac_window_bar {
                24.0 * scale
            } else if spec.title.is_some() {
                14.0 * scale
            } else {
                0.0
            };
            let mut block_y = wy + header_h + 14.0 * scale;
            let output_color = Color::rgb(0x97, 0x9e, 0xab);
            for (command, output) in blocks {
                draw_command_header(
                    &mut canvas,
                    command,
                    &spec.command_output_config,
                    wx + 16.0 * scale,
                    block_y + 5.0 * scale,
                    scale,
                );
                for (idx, line) in output.iter().enumerate() {
                    let y = block_y + 20.0 * scale + idx as f32 * 20.0 * scale;
                    canvas.draw_text(
                        &expand_tabs(line),
                        wx + 16.0 * scale,
                        y + 5.0 * scale,
                        CODE_ADVANCE * scale,
                        9.0 * scale,
                        output_color,
                    );
                }
                block_y += 20.0 * scale * (1 + output.len()) as f32;
            }
        }
    }

    // Border is drawn over the window and image edges.
    let border_color = from_hex(&spec.window.border_color);
    canvas.stroke_rounded_rect(wx, wy, ww, wh, radius, scale.max(1.0), border_color);

    if let Some(watermark) = &spec.watermark {
        if spec.window.margin_y >= 82.0 {
            let color = from_hex(&watermark.color);
            let text = single_line(&watermark.content);
            let advance = 15.0 * scale;
            let text_w = text.chars().count() as f32 * advance;
            let x = (canvas_w as f32 - text_w) / 2.0;
            let y = wy + wh + 50.0 * scale;
            canvas.draw_text(&text, x, y, advance, 30.0 * scale, color);
        }
    }

    Ok(png::encode_png(canvas_w as u32, canvas_h as u32, &canvas.pixels))
}

fn draw_window_chrome(canvas: &mut Canvas, spec: &SnapshotSpec, wx: f32, wy: f32, ww: f32, scale: f32) {
    if spec.window.mac_window_bar {
        let colors = [
            Color::rgb(0xff, 0x5e, 0x57),
            Color::rgb(0xff, 0xba, 0x2e),
            Color::rgb(0x2b, 0xc8, 0x41),
        ];
        for (i, color) in colors.iter().enumerate() {
            let cx = wx + (21.5 + i as f32 * 16.0) * scale;
            let cy = wy + 21.5 * scale;
            canvas.fill_circle(cx, cy, 5.0 * scale, *color);
        }
    }
    if let Some(title) = &spec.title {
        let color = from_hex(&spec.window.title_color);
        let text = single_line(title);
        let advance = 6.0 * scale;
        let text_w = text.chars().count() as f32 * advance;
        let x = wx + (ww - text_w) / 2.0;
        let y = if spec.window.mac_window_bar {
            wy + 8.0 * scale
        } else {
            wy + 3.0 * scale
        };
        canvas.draw_text(&text, x, y, advance, 9.0 * scale, color);
    }
}
