    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    //
    // The check is kept here, adjacent to the conversion loop.
    let _last = stops.last().unwrap();
    stops
        .iter()
        .map(|s| (s.position, from_hex(&s.color)))
        .collect()
}
