        "haskell" | "hs" => "haskell",
        "markdown" | "md" => "markdown",
        "text" | "plaintext" | "plain" | "txt" => "text",
        _ => {
            // Tokens can also be file extensions or syntax names.  Use
            // the same broad extension table as for file names before
