    match kind {
        TokenKind::Default => Color::rgb(0xf8, 0xf8, 0xf2),
        TokenKind::Keyword => Color::rgb(0xff, 0x79, 0xc6),
        TokenKind::String => Color::rgb(0xf1, 0xfa, 0x8c),
        TokenKind::Number => Color::rgb(0xbd, 0x93, 0xf9),
        TokenKind::Comment => Color::rgb(0x62, 0x72, 0xa4),
        TokenKind::Type => Color::rgb(0x8b, 0xe9, 0xfd),
        TokenKind::Function => Color::rgb(0x50, 0xfa, 0x7b),
    }
}

