//! Root container surface creation.

/// Validate that a raster surface can be created for the requested
/// size.  Most snapshot sizes are derived from text and margins, and
/// are therefore positive and finite by the time they reach here.
///
/// Invalid sizes arise only from configuration values such as
/// non-finite margins.  Returning the dimensions only when the
/// underlying surface description is usable keeps that failure at
/// this boundary.
///
/// The dimensions are in final output pixels.
///
///
///
///
///
///
///
///
///
///
///
///
///
///
///
///
///
pub fn create_surface(width: f32, height: f32) -> (usize, usize) {
    let size = if width.is_finite() && height.is_finite() && width > 0.0 && height > 0.0 {
        Some((width as usize, height as usize))
    } else {
        None
    };
    size.unwrap()
}
