use crate::cli::Args;
use codesnap_core::config::{CodeContent, HighlightLine};
use codesnap_core::render::RenderContent;
use std::io::Read;
use std::path::Path;

pub const CLIPBOARD_ERROR: &str = "Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable";

pub fn parse_range(input: &str, total_lines: usize) -> Result<(usize, usize), String> {
    let parts: Vec<&str> = input.split(':').collect();
    if parts.len() > 2 {
        return Err("Invalid range format".to_string());
    }
    if parts.len() == 1 {
        let value = parts[0].parse::<usize>().map_err(|e| e.to_string())?;
        return Ok((value, value));
    }
    if parts[0].is_empty() && parts[1].is_empty() {
        // Force the standard library's empty-integer error.
        let error = "".parse::<usize>().unwrap_err();
        return Err(error.to_string());
    }
    let start = if parts[0].is_empty() {
        1
    } else {
        parts[0].parse::<usize>().map_err(|e| e.to_string())?
    };
    let end = if parts[1].is_empty() {
        total_lines
    } else {
        parts[1].parse::<usize>().map_err(|e| e.to_string())?
    };
    Ok((start.min(end), start.max(end)))
}

fn parse_highlight_range(
    input: &str,
    code_range: (usize, usize),
    total_lines: usize,
    relative: bool,
    color: &str,
) -> Result<HighlightLine, String> {
    let (start, end) = parse_range(input, total_lines)?;
    let (range_start, range_end) = code_range;
    let (display_start, display_end) = if relative {
        let relative_limit = range_end - range_start;
        if end > relative_limit + 1 {
            return Err(format!(
                "The highlight end range should be less than or equal to {}",
                relative_limit
            ));
        }
        (start, end)
    } else {
        if start < range_start {
            return Err(format!(
                "The highlight start range should be greater than or equal to {}",
                range_start
            ));
        }
        if end > range_end {
            return Err(format!(
                "The highlight end range should be less than or equal to {}",
                range_end
            ));
        }
        (start - range_start + 1, end - range_start + 1)
    };
    if display_start == display_end {
        Ok(HighlightLine::Single(display_start as u32, color.to_string()))
    } else {
        Ok(HighlightLine::Range(
            display_start as u32,
            display_end as u32,
            color.to_string(),
        ))
    }
}

fn build_code_content(code: String, file_path: Option<String>, args: &Args) -> Result<CodeContent, String> {
    let original_lines: Vec<&str> = code.lines().collect();
    let total_lines = original_lines.len();
    let code_range = if let Some(range) = &args.range {
        parse_range(range, total_lines)?
    } else {
        let range = (1usize, total_lines);
        (range.0.min(range.1), range.0.max(range.1))
    };

    let selected: Vec<&str> = if args.range.is_none() {
        original_lines.clone()
    } else if code_range.0 == 0 || code_range.0 > total_lines {
        Vec::new()
    } else {
        let start_index = code_range.0 - 1;
        let end_index = code_range.1.min(total_lines);
        if end_index <= start_index {
            Vec::new()
        } else {
            original_lines[start_index..end_index].to_vec()
        }
    };
    let selected_code = selected.join("\n");

    let highlight_lines = if let Some(raw) = &args.raw_highlight_lines {
        serde_json::from_str::<Vec<HighlightLine>>(raw).map_err(|e| e.to_string())?
    } else {
        let mut highlights = Vec::new();
        if let Some(range) = &args.highlight_range {
            highlights.push(parse_highlight_range(
                range,
                code_range,
                total_lines,
                args.relative_highlight_range,
                &args.highlight_range_color,
            )?);
        }
        for range in &args.delete_line {
            highlights.push(parse_highlight_range(
                range,
                code_range,
                total_lines,
                args.relative_highlight_range,
                &args.delete_line_color,
            )?);
        }
        for range in &args.add_line {
            highlights.push(parse_highlight_range(
                range,
                code_range,
                total_lines,
                args.relative_highlight_range,
                &args.add_line_color,
            )?);
        }
        highlights
    };

    Ok(CodeContent {
        content: selected_code,
        language: args.language.clone(),
        file_path,
        highlight_lines,
        start_line_number: if args.has_line_number {
            Some(args.start_line_number.unwrap_or(1))
        } else {
            None
        },
    })
}

fn read_stdin_bytes() -> Result<Vec<u8>, String> {
    let mut bytes = Vec::new();
    std::io::stdin()
        .read_to_end(&mut bytes)
        .map_err(|e| e.to_string())?;
    Ok(bytes)
}

fn read_stdin_string() -> Result<String, String> {
    let bytes = read_stdin_bytes()?;
    String::from_utf8(bytes).map_err(|e| e.to_string())
}

fn read_code_file(path: &str) -> Result<String, String> {
    let path_ref = Path::new(path);
    if path_ref.exists() && !path_ref.is_file() {
        return Err("The file path is not a file".to_string());
    }
    std::fs::read_to_string(path).map_err(|e| e.to_string())
}

fn execute_commands(commands: &[String], skip: bool) -> Vec<(String, String)> {
    commands
        .iter()
        .map(|command| {
            let output_text = if skip {
                String::new()
            } else {
                let output = std::process::Command::new("sh")
                    .arg("-c")
                    .arg(command)
                    .output()
                    .expect("failed to execute process");
                let bytes = if output.status.success() {
                    output.stdout
                } else {
                    output.stderr
                };
                String::from_utf8_lossy(&bytes).into_owned()
            };
            (command.clone(), output_text)
        })
        .collect()
}

pub fn get_content(args: &Args) -> Result<RenderContent, String> {
    if let Some(commands) = &args.execute {
        return Ok(RenderContent::Command(execute_commands(commands, args.skip)));
    }
    if let Some(image) = &args.from_image {
        let bytes = match image {
            Some(value) => value.clone().into_bytes(),
            None => read_stdin_bytes()?,
        };
        return Ok(RenderContent::Image(bytes));
    }
    if let Some(path) = &args.from_file {
        let code = read_code_file(path)?;
        let content = build_code_content(code, Some(path.clone()), args)?;
        return Ok(RenderContent::Code(content));
    }
    if let Some(code_option) = &args.from_code {
        let code = match code_option {
            Some(code) => code.clone(),
            None => read_stdin_string()?,
        };
        let content = build_code_content(code, args.file_path.clone(), args)?;
        return Ok(RenderContent::Code(content));
    }
    if args.from_clipboard {
        if let Some(text) = crate::clipboard::get_clipboard_text() {
            let content = build_code_content(text, args.file_path.clone(), args)?;
            return Ok(RenderContent::Code(content));
        }
        return Err(CLIPBOARD_ERROR.to_string());
    }
    Err("No code snippet provided".to_string())
}
