use std::io::Write;
use std::process::{Command, Stdio};

fn find_program(name: &str) -> bool {
    if let Ok(path) = std::env::var("PATH") {
        for dir in path.split(':') {
            if !dir.is_empty() && std::path::Path::new(dir).join(name).exists() {
                return true;
            }
        }
    }
    false
}

pub fn get_clipboard_text() -> Option<String> {
    // In the headless environments this tool is normally tested in,
    // neither of the external clipboard bridges below is present and
    // the caller reports the X11 clipboard error.  When a desktop
    // session does provide one of them, use it in preference to
    // pretending the clipboard is unavailable.
    if std::env::var_os("WAYLAND_DISPLAY").is_some() && find_program("wl-paste") {
        if let Ok(output) = Command::new("wl-paste").arg("--no-newline").output() {
            if output.status.success() {
                return Some(String::from_utf8_lossy(&output.stdout).into_owned());
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() && find_program("xclip") {
        if let Ok(output) = Command::new("xclip")
            .args(["-selection", "clipboard", "-o"])
            .output()
        {
            if output.status.success() {
                return Some(String::from_utf8_lossy(&output.stdout).into_owned());
            }
        }
    }
    None
}

pub fn set_clipboard_text(text: &str) -> bool {
    if std::env::var_os("WAYLAND_DISPLAY").is_some() && find_program("wl-copy") {
        if let Ok(mut child) = Command::new("wl-copy").stdin(Stdio::piped()).spawn() {
            if let Some(stdin) = child.stdin.as_mut() {
                let _ = stdin.write_all(text.as_bytes());
            }
            if let Ok(status) = child.wait() {
                return status.success();
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() && find_program("xclip") {
        if let Ok(mut child) = Command::new("xclip")
            .args(["-selection", "clipboard"])
            .stdin(Stdio::piped())
            .spawn()
        {
            if let Some(stdin) = child.stdin.as_mut() {
                let _ = stdin.write_all(text.as_bytes());
            }
            if let Ok(status) = child.wait() {
                return status.success();
            }
        }
    }
    false
}

pub fn set_clipboard_image(png: &[u8]) -> bool {
    if std::env::var_os("WAYLAND_DISPLAY").is_some() && find_program("wl-copy") {
        if let Ok(mut child) = Command::new("wl-copy")
            .args(["--type", "image/png"])
            .stdin(Stdio::piped())
            .spawn()
        {
            if let Some(stdin) = child.stdin.as_mut() {
                let _ = stdin.write_all(png);
            }
            if let Ok(status) = child.wait() {
                return status.success();
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() && find_program("xclip") {
        if let Ok(mut child) = Command::new("xclip")
            .args(["-selection", "clipboard", "-t", "image/png"])
            .stdin(Stdio::piped())
            .spawn()
        {
            if let Some(stdin) = child.stdin.as_mut() {
                let _ = stdin.write_all(png);
            }
            if let Ok(status) = child.wait() {
                return status.success();
            }
        }
    }
    false
}
