mod config;

use base64::{engine::general_purpose::STANDARD, Engine as _};
use codesnap_core::config::{Breadcrumbs, CodeSnap, CommandOutputConfig, Content, Watermark, Window};
use codesnap_core::render::{render_snapshot, BreadcrumbsSpec, RenderContent, SnapshotSpec, WindowSpec};

const EGGS: [&str; 8] = [
    "Do you enjoy CodeSnap? Let's star it on GitHub!",
    "Enjoy CodeSnap? also try Freeze!",
    "Enjoy CodeSnap? also try Silicon!",
    "Share the code snapshot with your friends!",
    "Today is a great day to share CodeSnap!",
    "Rustaceans are the best!",
    "The CodeSnap is different from that one in VSCode extension market!",
    "CodeSnap is the best way to share code snippets!",
];

fn print_egg() {
    let seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0)
        ^ ((std::process::id() as u64) << 32);
    let mut state = seed ^ 0x9e37_79b9_7f4a_7c15;
    state ^= state << 13;
    state ^= state >> 7;
    state ^= state << 17;
    let message = EGGS[(state % EGGS.len() as u64) as usize];
    let width = message.chars().count() + 2;
    println!(" {}", "_".repeat(width));
    println!("< {} >", message);
    println!(" {}", "-".repeat(width));
    println!("        \\");
    println!("         \\");
    println!("            _~^~^~_");
    println!("        \\) /  o o  \\ (/");
    println!("          '_   -   _'");
    println!("          / '-----' \\");
}

fn default_window() -> Window {
    // This mirrors the values written into the automatically created
    // configuration file and is used only when a user-supplied
    // configuration omits the window section altogether.
    let value: Window = serde_json::from_str(
        r#"{
          "mac_window_bar": true,
          "shadow": {"radius": 20, "color": "#00000040"},
          "margin": {"x": 82, "y": 82},
          "border": {"width": 1, "color": "#ffffff30"},
          "title_config": {"color": "#ffffff", "font_family": "Pacifico"},
          "radius": 12
        }"#,
    )
    .expect("built-in window configuration is valid");
    value
}

fn resolve_window(config_window: Option<Window>, args: &cli::Args) -> WindowSpec {
    let window = config_window.unwrap_or_else(default_window);
    WindowSpec {
        mac_window_bar: args.mac_window_bar.unwrap_or(window.mac_window_bar),
        shadow_radius: args.shadow_radius.unwrap_or(window.shadow.radius),
        shadow_color: args.shadow_color.clone().unwrap_or(window.shadow.color),
        margin_x: args.margin_x.unwrap_or(window.margin.x),
        margin_y: args.margin_y.unwrap_or(window.margin.y),
        border_color: args.border_color.clone(),
        title_color: args.title_color.clone().unwrap_or(window.title_config.color.clone()),
        title_font_family: args
            .title_font_family
            .clone()
            .unwrap_or(window.title_config.font_family.clone()),
        radius: window.radius,
    }
}

fn resolve_watermark(config_watermark: Option<Watermark>, args: &cli::Args) -> Option<Watermark> {
    if let Some(content) = &args.watermark {
        let (font, color) = match &config_watermark {
            Some(w) => (w.font_family.clone(), w.color.clone()),
            None => ("Pacifico".to_string(), "#ffffff".to_string()),
        };
        Some(Watermark {
            content: content.clone(),
            font_family: args.watermark_font_family.clone().unwrap_or(font),
            color: args.watermark_color.clone().unwrap_or(color),
        })
    } else if let Some(mut watermark) = config_watermark {
        if let Some(font) = &args.watermark_font_family {
            watermark.font_family = font.clone();
        }
        if let Some(color) = &args.watermark_color {
            watermark.color = color.clone();
        }
        Some(watermark)
    } else {
        None
    }
}

struct ResolvedCodeConfig {
    font_family: String,
    breadcrumbs_separator: String,
    breadcrumbs_color: String,
    breadcrumbs_font_family: String,
}

fn resolve_code_config(snapshot: &CodeSnap, args: &cli::Args) -> ResolvedCodeConfig {
    let (config_font, config_breadcrumbs): (String, Option<Breadcrumbs>) =
        match &snapshot.code_config {
