        .or_else(|| config_breadcrumbs.as_ref().map(|b| b.font_family.clone()))
        .unwrap_or_default();
    ResolvedCodeConfig {
        font_family: args.code_font_family.clone().unwrap_or(config_font),
        breadcrumbs_separator: separator,
        breadcrumbs_color: color,
        breadcrumbs_font_family: font,
    }
}

fn create_ascii_snapshot(content: &RenderContent) -> Result<String, String> {
    match content {
        RenderContent::Code(code) => {
            let mut lines: Vec<String> = code.content.lines().map(|s| s.to_string()).collect();
            if lines.is_empty() {
                lines.push(String::new());
            }
            let width = lines.iter().map(|l| l.chars().count()).max().unwrap_or(0);
            let mut out = String::new();
            out.push_str(&format!("+{}+\n", "-".repeat(width + 2)));
            for line in &lines {
                out.push_str(&format!("| {}{} |\n", line, " ".repeat(width - line.chars().count())));
            }
            out.push_str(&format!("+{}+\n", "-".repeat(width + 2)));
            Ok(out)
        }
        _ => Err("The code content is not raw".to_string()),
    }
}

fn run() -> Result<(), String> {
    let matches = cli::build_cli().get_matches();
    let args = cli::parse_args(&matches);

    let loaded = config::load_config(args.config.as_deref())?;
    let cli_config = loaded.config;
    let snapshot_config = cli_config.snapshot_config.clone();

    // A non-code content embedded in the configuration takes
    // precedence over every command-line input source.
    let content: RenderContent = match &snapshot_config.content {
        Some(Content::Image(bytes)) => RenderContent::Image(bytes.clone()),
        Some(Content::Command(commands)) => RenderContent::Command(commands.clone()),
        _ => code::get_content(&args)?,
    };

    let resolved_code = resolve_code_config(&snapshot_config, &args);
    let breadcrumbs = match &content {
        RenderContent::Code(code) if args.has_breadcrumbs => code.file_path.as_ref().map(|path| BreadcrumbsSpec {
            separator: resolved_code.breadcrumbs_separator.clone(),
            color: resolved_code.breadcrumbs_color.clone(),
            font_family: resolved_code.breadcrumbs_font_family.clone(),
            file_path: path.clone(),
        }),
        _ => None,
    };

    if args.scale_factor < 1 {
        return Err("The scale factor must be greater than 1".to_string());
    }
    let background = snapshot_config
        .background
        .clone()
        .ok_or_else(|| "`background` must be initialized".to_string())?;

    if let Some(dir) = &loaded.home_config_dir {
        std::fs::create_dir_all(dir.join("remote_themes")).map_err(|e| e.to_string())?;
    }

    let spec = SnapshotSpec {
        content: content.clone(),
        window: resolve_window(snapshot_config.window.clone(), &args),
        theme: args
            .code_theme
            .clone()
            .or(snapshot_config.theme.clone())
            .unwrap_or_else(|| "candy".to_string()),
        background,
        watermark: resolve_watermark(snapshot_config.watermark.clone(), &args),
        title: args.title.clone(),
        breadcrumbs,
        line_number_color: args.line_number_color.clone(),
        code_font_family: resolved_code.font_family,
        command_output_config: snapshot_config
            .command_output_config
            .clone()
            .unwrap_or_default(),
        scale_factor: args.scale_factor,
        syntax_paths: snapshot_config.syntax_paths.clone(),
    };

    if args.snapshot_type == "ascii" {
        if args.output != "clipboard" {
            println!("\x1b[33m[WARN]\x1b[0m ASCII snapshot only supports copying to clipboard");
            if cli_config.print_eggs {
                print_egg();
            }
            return Ok(());
        }
        let ascii = create_ascii_snapshot(&content)?;
        if clipboard::set_clipboard_text(&ascii) {
            if !args.silent {
                println!(
                    "\x1b[32m[SUCCESS]\x1b[0m Snapshot saved to {} successful!",
                    args.output
                );
            }
            if cli_config.print_eggs {
                print_egg();
            }
            return Ok(());
        }
        return Err(code::CLIPBOARD_ERROR.to_string());
    }

    let _ = spec.code_font_family.clone();
    let _ = CommandOutputConfig::default();
    let png_bytes = render_snapshot(&spec)?;

    if args.output == "clipboard" {
        if clipboard::set_clipboard_image(&png_bytes) {
            if !args.silent {
                println!(
                    "\x1b[32m[SUCCESS]\x1b[0m Snapshot saved to {} successful!",
                    args.output
                );
            }
            if cli_config.print_eggs {
                print_egg();
            }
            return Ok(());
        }
        return Err(code::CLIPBOARD_ERROR.to_string());
    }

    let output_bytes: Vec<u8> = if args.output.ends_with(".png") {
        png_bytes
    } else if args.output.ends_with(".svg") {
        format!(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>",
            STANDARD.encode(&png_bytes)
        )
        .into_bytes()
    } else if args.output.ends_with(".html") {
        format!(
            "<img src=\"data:image/png;base64,{}\" />",
            STANDARD.encode(&png_bytes)
        )
        .into_bytes()
    } else {
        return Err("Unsupported output format".to_string());
    };

    let output_path = std::path::Path::new(&args.output);
    let actual_path = if output_path.is_dir() {
        let timestamp = chrono::Local::now().format("%Y-%m-%d_at_%H:%M:%S");
        output_path.join(format!("CodeSnap_{}", timestamp))
    } else {
        output_path.to_path_buf()
    };
    std::fs::write(&actual_path, output_bytes).map_err(|e| e.to_string())?;

    if !args.silent {
        println!(
            "\x1b[32m[SUCCESS]\x1b[0m Snapshot saved to {} successful!",
            args.output
        );
    }
    if cli_config.print_eggs {
        print_egg();
    }
    Ok(())
}

fn main() {
    if let Err(error) = run() {
        println!("\x1b[31m[ERROR]\x1b[0m {}", error);
        std::process::exit(1);
    }
}
