                        .map_err(|_| "Highlight code failed!".to_string())?;
                    children.sort_by_key(|e| e.path());
                    for child in children {
                        stack.push(child.path());
                    }
                } else if entry
                    .extension()
                    .and_then(|e| e.to_str())
