                        .map_err(|_| "Highlight code failed!".to_string())?;
                    let palette = parse_tm_theme(&content)?;
                    if let Some(stem) = entry.file_stem().and_then(|s| s.to_str()) {
                        themes.insert(stem.to_string(), palette);
                    }
                }
            }
        }
    }
    Ok(themes)
}

