new=r'''    /// Draw a soft shadow for a rounded rectangle.  The shadow shape
    /// is shifted slightly downwards and its alpha is evaluated with
    /// a Gaussian falloff from the signed distance to that shape.
    pub fn shadow_rounded_rect(&mut self, x: f32, y: f32, w: f32, h: f32, radius: f32, blur: f32, color: Color) {
        if blur <= 0.0 || !blur.is_finite() || color.a == 0 {
            return;
        }
        let sigma = (blur * 0.35).max(0.5);
        let offset_y = blur * 0.3;
        let spread = sigma * 3.0;
        let sx = x;
        let sy = y + offset_y;
        let (x0, x1) = self.clamp_range((sx - spread).floor() as i32, (sx + w + spread).ceil() as i32, self.width);
        let (y0, y1) = self.clamp_range((sy - spread).floor() as i32, (sy + h + spread).ceil() as i32, self.height);
        let cx = sx + w / 2.0;
        let cy = sy + h / 2.0;
        let hw = w / 2.0;
        let hh = h / 2.0;
        let r = radius.min(hw).min(hh).max(0.0);
        for yy in y0..y1 {
            for xx in x0..x1 {
                let px = xx as f32 + 0.5;
                let py = yy as f32 + 0.5;
                let qx = (px - cx).abs() - (hw - r);
                let qy = (py - cy).abs() - (hh - r);
                let outside = (qx.max(0.0).powi(2) + qy.max(0.0).powi(2)).sqrt();
                let inside = qx.max(qy).min(0.0);
                let sd = outside + inside - r;
                if sd > spread {
                    continue;
                }
                // Abramowitz-Stegun style erfc approximation through
                // the complementary error function integral form is
                // unnecessary here; a logistic approximation to the
                // Gaussian CDF is close at pixel accuracy.
                let t = sd / sigma;
                let cdf = 1.0 / (1.0 + (-1.702 * t).exp());
                let factor = 1.0 - cdf;
                let alpha = (color.a as f32 * factor).round() as u8;
                if alpha > 0 {
                    self.blend_pixel(xx, yy, Color::rgba(color.r, color.g, color.b, alpha));
                }
            }
        }
    }

'''
