p='core/src/canvas.rs';s=open(p).read()
start=s.index('    pub fn draw_image')
new=r'''    pub fn draw_image(&mut self, img: &crate::png::DecodedImage, x: f32, y: f32, w: f32, h: f32, radius: f32) {
        let (x0, x1) = self.clamp_range(x.floor() as i32, (x + w).ceil() as i32, self.width);
        let (y0, y1) = self.clamp_range(y.floor() as i32, (y + h).ceil() as i32, self.height);
        if img.width == 0 || img.height == 0 || w <= 0.0 || h <= 0.0 {
            return;
        }
        let sample = |sx: usize, sy: usize| -> [f32; 4] {
            let idx = (sy * img.width as usize + sx) * 4;
            let a = img.rgba[idx + 3] as f32 / 255.0;
            [
                img.rgba[idx] as f32 * a,
                img.rgba[idx + 1] as f32 * a,
                img.rgba[idx + 2] as f32 * a,
                img.rgba[idx + 3] as f32,
            ]
        };
        for yy in y0..y1 {
            for xx in x0..x1 {
                if !Self::rounded_rect_contains(xx as f32 + 0.5, yy as f32 + 0.5, x, y, w, h, radius) {
                    continue;
                }
                let src_x = (((xx as f32 + 0.5 - x) / w) * img.width as f32 - 0.5)
                    .clamp(0.0, (img.width - 1) as f32);
                let src_y = (((yy as f32 + 0.5 - y) / h) * img.height as f32 - 0.5)
                    .clamp(0.0, (img.height - 1) as f32);
                let sx0 = src_x.floor() as usize;
                let sy0 = src_y.floor() as usize;
                let sx1 = (sx0 + 1).min(img.width as usize - 1);
                let sy1 = (sy0 + 1).min(img.height as usize - 1);
                let tx = src_x - sx0 as f32;
                let ty = src_y - sy0 as f32;
                let c00 = sample(sx0, sy0);
                let c10 = sample(sx1, sy0);
                let c01 = sample(sx0, sy1);
                let c11 = sample(sx1, sy1);
                let mut premul = [0f32; 4];
                for i in 0..4 {
                    premul[i] = c00[i] * (1.0 - tx) * (1.0 - ty)
                        + c10[i] * tx * (1.0 - ty)
                        + c01[i] * (1.0 - tx) * ty
                        + c11[i] * tx * ty;
                }
                let alpha = premul[3].clamp(0.0, 255.0);
                if alpha <= 0.0 {
                    continue;
                }
                let straight = |v: f32| (v * 255.0 / alpha).round().clamp(0.0, 255.0) as u8;
                let color = Color::rgba(
                    straight(premul[0]),
                    straight(premul[1]),
                    straight(premul[2]),
                    alpha.round() as u8,
                );
                self.blend_pixel(xx, yy, color);
            }
        }
    }
