//! Background component helpers.
//!
//! A snapshot background is either a solid color or a linear
//! gradient described by two points and a list of color stops.
//! The renderer evaluates the gradient for every output pixel by
//! projecting that pixel onto the line between the two points.
//! This module owns the stop-related parts of that evaluation:
//! parsing the configured hexadecimal colors and interpolating
//! between adjacent stops.
//!
//! Stop positions are used in the order in which they appear in
//! the configuration.  Positions before the first stop take the
//! first color and positions after the final stop take the final
//! color, mirroring the behavior of the usual gradient shaders.

use crate::config::GradientStop;
use crate::utils::color::{from_hex, Color};

/// Return the color at normalized position `t` along a gradient.
///
/// `stops` must be in configuration order.  The interpolation is
/// performed channel by channel in RGBA space between the pair of
/// stops surrounding `t`; outside the interval covered by the
/// stops, the nearest end color is returned.  A single stop is a
/// solid background wherever it is positioned.
pub fn gradient_color_at(stops: &[(f32, Color)], t: f32) -> Color {
    if stops.is_empty() {
        return Color::rgb(0, 0, 0);
    }
    if stops.len() == 1 || t <= stops[0].0 {
        return stops[0].1;
    }
    if t >= stops[stops.len() - 1].0 {
        return stops[stops.len() - 1].1;
    }
    for pair in stops.windows(2) {
        let (position_before, color_before) = pair[0];
        let (position_after, color_after) = pair[1];
        if t >= position_before && t <= position_after {
            let fraction = if (position_after - position_before).abs() < f32::EPSILON {
                0.0
            } else {
                (t - position_before) / (position_after - position_before)
            };
            return Color::rgba(
                (color_before.r as f32 + (color_after.r as f32 - color_before.r as f32) * fraction).round() as u8,
                (color_before.g as f32 + (color_after.g as f32 - color_before.g as f32) * fraction).round() as u8,
                (color_before.b as f32 + (color_after.b as f32 - color_before.b as f32) * fraction).round() as u8,
                (color_before.a as f32 + (color_after.a as f32 - color_before.a as f32) * fraction).round() as u8,
            );
        }
    }
    stops[stops.len() - 1].1
}

/// Parse the configured gradient stops into colors.
///
/// Colors are parsed eagerly so a malformed hexadecimal value is
/// reported before any part of the snapshot is drawn.  The final
/// stop is also accessed before the parsed vector is returned:
/// a gradient shader needs at least that color to extend to the
/// end of the background, so an empty configuration cannot be
/// turned into a usable gradient at all.
pub fn parse_stops(stops: &[GradientStop]) -> Vec<(f32, Color)> {
    let mut parsed = Vec::with_capacity(stops.len());
    for stop in stops {
        let color = from_hex(&stop.color);
        parsed.push((stop.position, color));
    }
    // Access the final configured stop for the reason described
    // above; the parsed form of it is already in `parsed`.
    stops.last().unwrap();
    parsed
}
